"""Contenido original del taller. No descarga materiales ni depende de servicios."""
import json
from pathlib import Path
from reading_support import glossaries
ROOT = Path(__file__).resolve().parents[1]
PACKS = {"a1": [], "a2": [], "b1": []}

def add(level, insight, contrast, text, facts, transfer, challenge):
    """Tres explicaciones, contraste corregido, lectura, tres datos, producción."""
    pieces = insight.split('||')
    assert len(pieces) == 3
    PACKS[level].append(dict(insights=pieces, contrast=contrast.split('|'), text=text,
                            facts=[f.split('|') for f in facts.split('~')],
                            transfer=transfer.split('|'), challenge=challenge))

# A1: lenguaje cotidiano, apoyos concretos y frases cortas.
add('a1',
'El saludo depende de la situación, no de traducir buenas noches palabra por palabra. Al entrar por la tarde-noche dices Good evening; al despedirte para dormir, Good night. Hi es cercano y Hello funciona en muchas situaciones. Contesta el saludo antes de iniciar tu pregunta.||Aprende la presentación como un intercambio: pregunta, respuesta y devolución de la pregunta. My name is… aporta el nombre; Nice to meet you responde al primer encuentro. Al deletrear, di una letra cada vez y confirma el resultado. No necesitas contar más datos personales.||Pedir una repetición es una habilidad de comunicación. Primero indica la dificultad con Sorry; después pide una acción concreta: repeat, speak slowly o spell. Repite lo que sí entendiste y pregunta por la parte que falta. Practica estas frases hasta poder decirlas sin leer.',
'Good evening, Eva.|Good night, Eva. [al llegar]|Good evening saluda al llegar; Good night suele despedir antes de dormir.',
"Hello! My name is Mila. This is my first day at the English club. A man says, 'Good afternoon. I am Tom.' I say, 'Hello, Tom. Nice to meet you.' He asks my name. I say, 'Mila. M, I, L, A.' Tom writes it on a small card. A woman says a new word. I do not understand. 'Can you repeat that, please?' I ask. She speaks slowly. Now I understand. At the end of the class, I say, 'Thank you. Goodbye!' My card is in my bag. Tomorrow I can say hello again.",
'What is her name?|Mila~Who writes the name?|Tom~Where is the card at the end?|in her bag',
'Saluda a una persona nueva y preséntate.|Pídele que deletree su nombre; tú deletrea uno inventado.|No entiendes una palabra: pide repetición y despídete.',
'Cambia el encuentro de la tarde a la mañana. Reescribe el saludo y mantén una presentación, una petición de ayuda y una despedida.')
add('a1',
'Be une a una persona con una identidad, una descripción o un lugar. En I am a student, student dice quién eres; en I am at home, at home dice dónde estás. El inglés necesita el sujeto: no basta con Am tired. Identifica primero I, you, he, she, it, we o they.||Las contracciones son frecuentes al hablar: I am pasa a I’m y she is a she’s. La negación conserva not: I’m not tired. Aprende la forma completa para reconocer sus partes y luego practica la corta. Una contracción no cambia el significado básico.||Para preguntar con be intercambia verbo y sujeto: You are ready se convierte en Are you ready? En una respuesta breve repite el sujeto adecuado: Yes, I am. No uses Yes, I’m como respuesta afirmativa aislada. Añade un dato después si quieres mantener la conversación.',
'Are they students?|Do they are students?|Las preguntas con be no llevan do: se coloca are antes de they.',
"I am Omar. I am a new student, and I am a little tired today. My friend Eva is in my class. She is not tired; she is happy. Our teacher is Mr Lee. He is in the classroom with two visitors. They are teachers too. 'Are you ready?' he asks. 'Yes, we are,' we say. My book is on the table, but my pen is not here. Eva has a blue pen for me. We are not late. The lesson is at ten, and it is only nine fifty. We are ready now.",
'Who is tired?|Omar~Who is the teacher?|Mr Lee~What colour is the pen?|blue',
'Preséntate con una ocupación real o imaginaria.|Describe dónde están dos personas usando is y are.|Haz tres preguntas con be y contéstalas brevemente.',
'Describe a tres personajes: quiénes son, cómo están y dónde están. Incluye una negación y una pregunta.')
add('a1',
'País y nacionalidad tienen funciones distintas: from Peru expresa origen; Peruvian describe nacionalidad. Ambos llevan mayúscula en inglés. Para una ciudad también puedes usar from: I am from Lima. No pongas a delante de una nacionalidad usada como adjetivo.||La edad se construye con be: I am eighteen. Years old es opcional, pero no traduzcas tengo literalmente con have. Distingue thirteen de thirty escuchando el acento. En números de teléfono suele decirse cada cifra por separado; repite grupos pequeños para confirmar.||Un formulario pide información breve, no oraciones largas. First name es nombre; surname o last name, apellido. En un correo electrónico, at representa @ y dot un punto. Para practicar utiliza datos ficticios: el objetivo es poder entender y confirmar información, no publicar tus datos reales.',
'I am twenty years old.|I have twenty years.|La edad en inglés se expresa normalmente con be.',
"My name is Diego Cruz. I am nineteen years old, and I am from Peru. I am Peruvian. My friend Aiko is from Japan. She is twenty. We are at a language school in Canada. The woman at the desk asks for our names. I spell Cruz: C, R, U, Z. She asks, 'Nineteen or ninety?' 'Nineteen,' I say. She writes nineteen on the form. Aiko checks her name too. Our class is in room twelve. We do not know the building, so we ask for help. A student shows us the room.",
'How old is Diego?|nineteen~Where is Aiko from?|Japan~What is the room number?|twelve',
'Completa una ficha con nombre, país, nacionalidad y edad ficticios.|Lee dos números parecidos y pide confirmación.|Pregunta el número de aula y repítelo para comprobarlo.',
'Presenta a tu compañero imaginario sin mirar la ficha. Cambia I am por he is o she is según el personaje.')
add('a1',
'A y an presentan un elemento singular no identificado. La elección depende del sonido inicial: an apple, pero a university porque comienza con un sonido parecido a /j/. The señala algo que ambas personas pueden identificar. Compara a pen con the pen on your desk.||Los objetos contables permiten singular y plural. La mayoría añade -s; algunas palabras requieren -es o cambian de forma, como box/boxes y child/children. No pongas a delante de un plural. Practica el sustantivo junto con su determinante para aprender una combinación completa.||This y these señalan cerca; that y those, más lejos. This y that combinan con is; these y those con are. La distancia puede depender del contexto del hablante. Mientras señalas objetos, alterna uno y varios: This is a cup; these are cups.',
'These are my books.|These is my books.|These es plural y necesita are.',
"This is our art room. There is a big table in the middle. This is a red pencil, and that is a blue pen near the window. These are my notebooks. Those boxes by the door are for the teacher. There is an orange in a small bag, but it is not for the lesson. It is my lunch! A child points to a picture. 'Is that a cat?' she asks. 'No, it is an owl,' says the teacher. We need paper and pencils today. At the end, we put the pencils in the boxes.",
'What colour is the pencil?|red~Where are the boxes?|by the door~What animal is in the picture?|an owl',
'Señala dos objetos cercanos y dos lejanos.|Describe uno y después varios del mismo tipo.|Presenta un objeto con a/an y vuelve a mencionarlo con the.',
'Haz una pequeña lista del material de una clase. Usa a, an, this, these y un plural irregular que hayas estudiado.')
add('a1',
'El posesivo depende del dueño, no del objeto. His sister significa su hermana de él; her brother, su hermano de ella. My y your no cambian ante plurales: my book y my books. Para preguntar de quién es algo usa Whose…?, una forma distinta de Who is…?||El apóstrofo puede indicar posesión: Anna’s bag es la bolsa de Anna. Con un plural regular terminado en s se añade solo el apóstrofo: my parents’ house. No confundas esta marca con el plural sin apóstrofo. Un árbol familiar ayuda a ver quién se relaciona con quién.||En inglés brother y sister especifican el vínculo. Parents significa padres, no parientes en general; para eso existe relatives. Puedes hablar de una familia inventada o de personas importantes para ti. Presenta primero el nombre y luego la relación para evitar un su ambiguo.',
'Her brother is ten.|She brother is ten.|Her acompaña al sustantivo; she funciona como sujeto.',
"This is a photo of my family. My name is Sara. My brother is Nico, and my sister is Elena. Nico is ten. Elena is a student. Our parents are Rosa and Luis. Their house is near the park. My grandmother Ana is in the photo too. She is next to Elena. The small dog is Nico's dog. His name is Max. My uncle is not in the photo because he is at work. On Sunday, we have lunch together. I show the photo to my friend and tell her everyone's name.",
'Who is Sara’s brother?|Nico~Where is the house?|near the park~Whose dog is Max?|Nico’s',
'Dibuja una familia inventada de seis personas.|Explica cuatro relaciones con my, his, her y their.|Describe de quién son tres objetos con nombres y apóstrofo.',
'Presenta a alguien de la foto imaginaria. Evita repetir el nombre en todas las frases: alterna nombre, pronombre y posesivo.')
add('a1',
'Un adjetivo suele ir antes del sustantivo: a tall woman. También puede aparecer después de be: the woman is tall. No añade -s en plural. Para describir a alguien combina rasgos visibles con cualidades respetuosas, sin suponer su personalidad solo por su aspecto.||Have y has expresan posesión y características: I have brown eyes; she has brown eyes. En presente simple, las preguntas usan do/does y have: Does she have…? Después de does no uses has. Hair suele ser incontable cuando describe todo el cabello.||Have got también expresa posesión en muchos contextos, especialmente británicos: She has got a bike. Su pregunta es Has she got…? Mantén el mismo patrón dentro del ejercicio. Aprende a reconocer ambos y elige uno coherente al producir tu descripción.',
'She has long hair.|She is long hair.|Se usa has para el cabello; be sirve para adjetivos como tall.',
"I am looking for my friend at the station. Her name is Jess. She is tall, and she has short brown hair. She has green eyes and a small red bag. My brother says, 'Is that Jess by the shop?' The woman there is tall too, but she has long hair. It is not Jess. Then I see a red bag near the door. Jess is there with her brother. He is short and has a blue coat. Jess is friendly. She says hello to my brother, and we walk to the bus stop together.",
'Where are they looking for Jess?|at the station~What colour is her bag?|red~Is Jess’s hair long or short?|short',
'Describe a un personaje sin decir su nombre.|Contrasta dos personas con is y has.|Haz una pregunta con have y otra con have got.',
'Escribe una descripción para encontrar a una persona en una estación. Incluye cuatro detalles claros y comprueba el orden de los adjetivos.')
add('a1',
'There is presenta algo que existe en un lugar; it is describe una cosa ya mencionada. There is a sofa. It is blue. Con plural usa there are. Al negar, there isn’t a chair significa que no hay ni una silla; there aren’t any chairs habla de sillas en plural.||Is there…? pregunta por un elemento o sustancia; Are there…? por varios elementos contables. A una pregunta breve responde Yes, there is o No, there aren’t. No uses there para decir ellos: there are students significa hay estudiantes.||Las preposiciones describen relaciones: in contiene, on toca una superficie, under está debajo, next to está al lado y between necesita dos referencias. No memorices solo traducciones: coloca tres objetos de verdad y cambia uno de posición mientras lo describes.',
'There are two windows.|There is two windows.|Two windows es plural: corresponde there are.',
"Our new flat is small, but it is bright. There are two bedrooms and a kitchen. In the living room, there is a green sofa. A small table is in front of it. My books are on the table, and a box is under it. There is a lamp next to the sofa. There are no pictures on the wall yet. My room has a bed and a desk. The desk is between the bed and the window. I like my room because I can read by the window in the afternoon.",
'How many bedrooms are there?|two~What is under the table?|a box~Where is the desk?|between the bed and the window',
'Dibuja una habitación y describe cinco posiciones.|Pregunta si hay una lámpara y varias sillas.|Añade un objeto con there is y descríbelo después con it is.',
'Tu compañero dibuja sin ver tu plano. Dale instrucciones claras y luego compara: ¿qué referencia faltó o fue ambigua?')
add('a1',
'El presente simple describe rutinas, no solo lo que ocurre ahora. Con I, you, we y they usa la forma básica: I work. Añade una expresión temporal para concretar: every morning. Aprende grupos como get up, have breakfast y go to bed como unidades con significado.||Con he, she e it aparece -s o -es: works, watches, goes. Si una consonante precede a y, cambia a -ies: study/studies; play/plays conserva y. Have cambia a has. Marca quién realiza la acción antes de decidir la terminación.||First, then, after that y finally ordenan una rutina. After breakfast introduce un momento; after I have breakfast introduce una oración. En este nivel puedes escribir frases cortas y unirlas poco a poco. Cambia la hora o el sujeto para comprobar que sabes adaptar el modelo.',
'My sister studies at night.|My sister study at night.|My sister equivale a she: studies lleva la terminación de tercera persona.',
"Ben works in a small shop. He gets up at six thirty and has breakfast at seven. He walks to work because the shop is near his home. The shop opens at eight. Ben helps customers and puts books on the shelves. At one, he has lunch with his friend. He finishes work at four. Then he goes home and studies English for twenty minutes. His sister studies with him on Mondays. In the evening, he cooks dinner. Finally, he reads a book and goes to bed at ten. On Sundays, the shop is closed.",
'How does Ben go to work?|he walks~When does he finish work?|at four~What does he study?|English',
'Cuenta tu rutina con seis acciones y horas.|Vuelve a contarla como si hablaras de tu hermano o amiga.|Compara un día de estudio con un día libre.',
'Escribe dos rutinas conectadas: la tuya con I y la de otra persona con he/she. Revisa cada verbo de tercera persona.')
add('a1',
'Don’t y doesn’t llevan la negación del presente simple. Después, el verbo principal vuelve a su forma básica: She doesn’t work. La -s ya está representada en does. Una negación corrige información o indica algo que no forma parte de la rutina.||Para preguntar usa Do/Does + sujeto + verbo. Las respuestas breves conservan el auxiliar: Yes, he does; No, we don’t. No respondas yes a una pregunta abierta como Where do you live? Esa pregunta necesita un lugar.||What, where, when, who y why piden información distinta. Colócalos antes de do/does en las preguntas de este nivel. Lee la respuesta esperada para elegir la palabra interrogativa. Haz una pregunta de seguimiento para convertir el ejercicio en una conversación.',
'Does she work here?|Does she works here?|Después de does se usa work, sin -s.',
"A new student joins our class. His name is Alex. 'Where do you live?' I ask. 'I live near the library,' he says. He does not take the bus to school. He walks with his cousin. 'Does your cousin study here too?' 'Yes, she does. She is in another class.' I ask what he does after school. He plays football on Tuesdays, but he does not play every day. On Fridays, he helps at home. We both like music. I ask, 'Do you play the guitar?' He says, 'No, I don't, but I sing.'",
'Where does Alex live?|near the library~Who walks with him?|his cousin~Does he play the guitar?|no',
'Entrevista a un personaje sobre lugar, horario y aficiones.|Da dos respuestas negativas y añade el dato correcto.|Haz una pregunta de seguimiento después de cada respuesta.',
'Redacta una entrevista de ocho turnos. Combina preguntas de sí/no y preguntas abiertas; evita usar does con el verbo en -s.')
add('a1',
'La hora puede decirse con números: seven thirty. También existen half past seven y a quarter past seven. Usa at con una hora concreta, on con un día e in con un mes o una parte del día; at night es una combinación frecuente que conviene aprender completa.||Las fechas varían en su escritura entre países. Para evitar confusiones, escribe el nombre del mes cuando sea importante. Monday y January llevan mayúscula. Before, after y from…to… ayudan a entender un horario sin traducir cada palabra.||Always, usually, sometimes y never expresan frecuencia aproximada. Van normalmente antes del verbo principal y después de be: I usually walk; I am usually early. Never ya es negativo. Every day son dos palabras cuando significa todos los días.',
'She is usually early.|She usually is early. [orden neutro del curso]|El lugar habitual del adverbio es después de be. Otros órdenes pueden enfatizar ideas, pero practica primero el neutro.',
"Our sports club has a new timetable. On Mondays, the swimming class is at half past five. On Wednesdays, the dance class starts at six fifteen. I usually arrive ten minutes early. My friend Kim sometimes arrives late because her bus is slow. We never go on Fridays because the club is closed. In July, the Saturday class is in the morning, from nine to ten. Today is Wednesday. I look at the clock: it is a quarter to six. I have thirty minutes before the dance class. I put my shoes in my bag and leave.",
'When is the swimming class?|on Mondays~Why is Kim sometimes late?|her bus is slow~What time does Wednesday’s class start?|six fifteen',
'Lee un horario y di tres horas de dos maneras.|Explica con qué frecuencia haces cuatro actividades.|Acuerda una cita indicando día, fecha y hora sin ambigüedad.',
'Crea una semana realista de estudio. Escribe cinco frases con at, on e in y dos con adverbios de frecuencia.')
add('a1',
'Like + sustantivo expresa un gusto: I like music. Like/love/enjoy + -ing permite hablar de actividades. Dislike o don’t like expresan que algo no te gusta. Añade because para explicar una preferencia y evitar listas que no comunican mucho.||Can expresa capacidad y no cambia con he/she: she can swim. Después lleva verbo básico sin to. Para negar usa can’t o cannot. En preguntas invierte can y sujeto. Una capacidad puede ser parcial: I can speak a little English.||Los pronombres objeto sustituyen a quien recibe una acción: I know her; she helps me. Después de una preposición también aparecen: with us, for him. Distingue I like him de he likes me señalando quién siente el gusto y a quién se refiere.',
'She can play the piano.|She can plays the piano.|Can va seguido del verbo básico y no añade -s.',
"Our school has a music evening. I like singing, but I cannot play the piano. My friend Hana can play it very well. She likes helping me with new songs. We practise together on Tuesdays. My brother does not enjoy singing, but he can draw. He makes a picture for us. At the music evening, I am nervous. Hana says, 'You can do it.' She plays the piano, and I sing a short song. Our friends listen to us. After the song, my brother smiles. I like sharing music with people, even when I feel nervous.",
'What can Hana play?|the piano~What can the brother do?|draw~When do they practise?|on Tuesdays',
'Di tres gustos y explica uno con because.|Describe dos capacidades y una limitación.|Sustituye nombres por me, him, her, us o them en ejemplos propios.',
'Organiza un pequeño evento: quién puede cantar, dibujar o cocinar. Asigna tareas según sus capacidades y preferencias.')
add('a1',
'Un sustantivo contable permite one/two: two apples. Un incontable se mide con una unidad: a glass of water, two bags of rice. La categoría depende a veces del uso: chicken puede nombrar un animal o carne. Empieza con combinaciones frecuentes y concretas.||Some suele aparecer en afirmaciones y any en preguntas y negaciones. Algunas ofertas y peticiones usan some porque se espera una respuesta positiva: Would you like some water? No conviertas la regla inicial en una prohibición absoluta; reconoce el propósito de la frase.||How many acompaña a un plural contable; how much a un incontable. La respuesta puede indicar un recipiente: two bottles. Much/many preguntan cantidad; a lot of sirve con ambos tipos. Practica haciendo una lista con unidades reales, no traduciendo solo mucho.',
'How much rice do we need?|How many rice do we need?|Rice se trata como incontable; para contar puedes hablar de bags of rice.',
"We are making lunch for four people. There are some tomatoes in the fridge, but there is not any cheese. We need bread, rice and a little milk. 'How many tomatoes have we got?' asks my father. 'Six,' I say. 'And how much rice do we need?' 'One cup is enough for this recipe.' My sister writes the shopping list. She adds two bottles of water and three apples. At the shop, we check the list before we pay. We do not buy eggs because there are ten at home. We carry the bags together.",
'How many people is lunch for?|four~How many tomatoes are there?|six~Why don’t they buy eggs?|there are ten at home',
'Clasifica ocho alimentos por su uso contable o incontable.|Pide cantidades usando recipientes y medidas.|Pregunta qué hay y qué falta para una comida.',
'Planifica una compra para tres personas. Escribe cinco cantidades y formula una pregunta con how much y otra con how many.')
add('a1',
'En una cafetería, I’d like… pide algo con cortesía. La contracción equivale a I would like. Can I have…? también funciona. Incluye el producto, la cantidad y cualquier detalle importante. Escucha la confirmación antes de dar por terminado el pedido.||I like coffee habla de un gusto general; I’d like a coffee expresa un deseo ahora. A coffee significa aquí una ración o taza. No hace falta explicar toda la gramática para usar la expresión, pero sí reconocer que las dos frases tienen propósitos distintos.||La interacción continúa después de pedir: Anything else? ofrece añadir algo; That’s all, thanks cierra el pedido. For here or to take away? pregunta dónde lo consumirás. Comprueba el total y pide la cuenta o el recibo según el contexto.',
'I’d like a tea, please.|I like a tea, please. [para pedir ahora]|Would like expresa el pedido actual; like expresa normalmente un gusto.',
"Leo and his friend visit a small café. Leo looks at the menu. A sandwich is four pounds, and tea is two pounds. 'I'd like a cheese sandwich and a tea, please,' he says. The server asks, 'For here or to take away?' 'For here,' says Leo. His friend orders water. 'Anything else?' the server asks. 'No, that's all, thanks.' They sit near the window. The tea is hot, so Leo waits. After lunch, he asks for the bill. His food and drink cost six pounds. He pays and thanks the server before leaving.",
'What sandwich does Leo order?|cheese~Where do they sit?|near the window~How much are Leo’s food and drink?|six pounds',
'Pide dos productos y una bebida.|Responde a una oferta de añadir algo y confirma para llevar o tomar allí.|Pide la cuenta y comprueba un total sencillo.',
'Representa cliente y camarero. En una segunda versión, un producto se ha terminado: pide una alternativa.')
add('a1',
'Un precio puede decirse con la moneda o, cuando el contexto es claro, solo con los números. Distingue la cantidad de artículos de su precio. How much is this shirt? pregunta por una; How much are these shoes? por un plural.||Size pregunta talla y colour/color, color. Usa too big o too small para explicar un problema básico. Can I try it on? pide probar una prenda singular; them sustituye un plural como shoes. Confirma antes de comprar si buscas una talla diferente.||Los comparativos cortos suelen añadir -er: cheaper, smaller. Se usa than para introducir la segunda opción. No todos siguen la misma forma: good pasa a better. Describe una diferencia concreta y relaciona la elección con lo que necesitas.',
'These shoes are cheaper than those.|These shoes are more cheaper than those.|Cheaper ya contiene la comparación: no añadas more.',
"Maya needs a coat for winter. She goes to a shop with her aunt. The first coat is blue and costs forty pounds. Maya tries it on, but it is too small. The assistant brings a green coat in a bigger size. It costs thirty-five pounds. 'This one is cheaper,' says her aunt. Maya likes the colour, and the coat is warm. She looks at a black coat too, but it is very long. She chooses the green one. At the desk, she pays by card and puts the receipt in her bag.",
'Why doesn’t Maya buy the blue coat?|it is too small~Which coat does she choose?|the green one~How does she pay?|by card',
'Pregunta precio, talla y color de una prenda.|Compara dos opciones con una diferencia real.|Explica por qué una prenda no te sirve y pide otra.',
'Escribe un diálogo de compra con ocho turnos. Incluye una talla incorrecta, una alternativa y una decisión justificada.')
add('a1',
'Excuse me sirve para llamar la atención antes de preguntar por un lugar. Where is…? pide su ubicación. Is there a… near here? pregunta si existe uno cerca. Si no entiendes la respuesta, pide una repetición o confirma un punto concreto del recorrido.||El imperativo usa la forma básica sin sujeto: Go straight; turn left. Para negar, don’t: Don’t cross here. Across indica pasar al otro lado; past, seguir más allá de una referencia. Dibuja el recorrido para comprobar que las instrucciones tienen sentido.||Una buena ruta se divide en pasos cortos y referencias visibles. Next to identifica el destino por su vecino; opposite, por lo que está enfrente. Comprueba izquierda y derecha desde la perspectiva de quien camina. No basta con memorizar nombres de calles.',
'Turn left at the bank.|Turn to left at the bank.|La instrucción habitual es turn left, sin to.',
"I am in a new town, and I need the library. I ask a woman near the station. She says, 'Go straight along this road. Turn right at the bank. Walk past the supermarket. The library is opposite the park.' I repeat, 'Right at the bank?' 'Yes,' she says. I follow the road and see the bank. After the supermarket, there is a large green park on my left. The library is on my right. It has a blue door. I go inside and ask for a map of the town. The woman at the desk gives me one.",
'Where should the person turn right?|at the bank~What is opposite the library?|the park~What colour is the library door?|blue',
'Dibuja un plano con cinco lugares.|Da una ruta de cuatro pasos a un destino.|Confirma un giro y pide ayuda si falta una referencia.',
'Cambia el punto de salida del plano y escribe una segunda ruta al mismo lugar. Léela mientras trazas el camino.')
add('a1',
'By bus, by train y by car describen el medio de transporte sin artículo. On foot significa a pie. Take the bus describe la acción habitual de usarlo. Para un viaje concreto, añade origen, destino y hora: from Lima to… evita confundir las dos ciudades.||Single/one-way es solo ida; return/round-trip incluye vuelta. Las palabras cambian entre variedades de inglés. How much is a ticket to…? pregunta precio; What time does it leave? pregunta salida. Lee los encabezados del horario antes de interpretar los números.||Una reserva sencilla necesita nombre, fecha, número de personas y, según el servicio, número de noches o trayecto. Confirma los datos en voz alta. Un error en un número puede cambiar todo el plan, así que repetirlo es más útil que decir yes automáticamente.',
'I go to work by bus.|I go to work by the bus. [medio en general]|By bus nombra el medio sin artículo. Take the bus usa otra estructura.',
"Eva wants to visit her cousin on Saturday. She goes to the bus station on foot. 'A return ticket to Greenford, please,' she says. The ticket costs twelve pounds. The bus leaves at nine twenty from stop four. Eva repeats the time and the stop number. She has a small bag and a sandwich. At nine ten, she waits at stop four. A bus arrives, but it goes to another town. She checks the name before getting on. Her bus arrives five minutes later. She shows her ticket and sits by the window.",
'What kind of ticket does Eva buy?|a return ticket~What time does her bus leave?|nine twenty~Which stop does she need?|four',
'Compra un billete indicando destino y tipo.|Pregunta hora y lugar de salida; repite ambos datos.|Explica cómo llegas a la estación desde tu casa.',
'Diseña un viaje corto con presupuesto y dos horarios. Escribe el intercambio necesario para comprar el billete correcto.')
add('a1',
'El presente continuo necesita dos piezas: am/is/are y verbo en -ing. El verbo be cambia con el sujeto; -ing se mantiene. I am reading describe una actividad en desarrollo. Sin am, la oración está incompleta. Observa quién actúa y qué está haciendo.||Para negar, añade not después de be; para preguntar, coloca be antes del sujeto. Algunas grafías cambian: make/making, run/running. No dupliques siempre la última consonante. Aprende las formas frecuentes con ejemplos y consulta las nuevas.||El presente simple habla de hábitos y el continuo de acciones actuales en este primer contraste. He works here y he is working now pueden ser verdaderos a la vez. Elige según el mensaje que quieres comunicar; now ayuda, pero no sustituye entender el contexto.',
'They are playing outside.|They playing outside.|Falta are: el presente continuo necesita be + -ing.',
"It is Saturday afternoon, and our family is at home. My father usually cooks, but today my mother is making lunch. My brother is washing the tomatoes. I am setting the table. The dog is sleeping under a chair. Outside, two children are playing with a ball. They play there every weekend. The phone rings. My aunt asks, 'What are you doing?' I say, 'We are getting lunch ready.' She is walking to our house. We put another plate on the table. Today we are eating together in the garden because the weather is warm.",
'Who is making lunch today?|the mother~What is the dog doing?|sleeping~Where are they eating today?|in the garden',
'Describe una escena con cinco acciones simultáneas.|Pregunta qué está haciendo una persona y niega una acción incorrecta.|Contrasta dos hábitos con lo que ocurre hoy.',
'Escribe un pie de foto inventado con acciones en continuo. Añade dos frases en simple que expliquen hábitos de los personajes.')
add('a1',
'Para hablar del tiempo usa it: It is cold; it is raining. Cold es adjetivo y raining forma parte de un verbo en continuo. No digas is cold sin sujeto. The weather is… también sirve cuando el tiempo es el tema explícito de la oración.||Wear describe tener ropa puesta; put on, la acción de ponérsela. En una foto, She is wearing a coat describe el estado visible. Shoes y trousers son plurales en las expresiones frecuentes de ropa; usa are o them cuando corresponda.||Because conecta una decisión con su motivo: I am wearing a coat because it is cold. But introduce contraste y and suma información. Compara climas de lugares y estaciones sin asumir que diciembre siempre es frío: las estaciones dependen del lugar.',
'It is raining today.|Is raining today.|El inglés requiere el sujeto it al describir el clima de esta manera.',
"My friend lives in a different country. Today we talk on the phone. It is sunny and hot where she lives. She is wearing a T-shirt and shorts. Here it is cold and windy. I am wearing a coat, a scarf and warm shoes. I want to walk to the shop, but dark clouds are coming. I take an umbrella from the door. Five minutes later, it is raining. My friend is surprised because she is going to the beach. We laugh about our different weather. I tell her I like sunny days, but I enjoy cool evenings too.",
'What is the weather like where the friend lives?|sunny and hot~What does the speaker take?|an umbrella~Where is the friend going?|to the beach',
'Describe el clima de dos lugares.|Elige ropa para cada lugar y explica por qué.|Distingue ponerse una prenda de llevarla puesta.',
'Escribe un mensaje a quien te visita: clima previsto como dato del ejercicio, tres prendas útiles y una actividad apropiada.')
add('a1',
'Para sensaciones usa be con adjetivos: I am tired, hungry o thirsty. Have aparece en expresiones como I have a headache. No existe una única traducción de tener. Aprende la combinación completa y señala qué parte del cuerpo menciona.||En el cuerpo hay plurales irregulares frecuentes: foot/feet y tooth/teeth. My head hurts expresa una molestia en singular; my feet hurt, en plural. Puedes describir cuándo ocurre algo con today o at night sin intentar dar un diagnóstico.||En una situación de ayuda, comunica primero la necesidad y después pide una acción concreta: Can I sit down? Can you help me? Practica entender instrucciones simples como sit here o drink some water. Estas frases son aprendizaje de idioma, no una evaluación de salud.',
'I am thirsty.|I have thirsty.|Thirsty es un adjetivo y se combina con be.',
"It is a warm day, and Sam is walking with his class. After an hour, he feels tired. His feet hurt, and he is thirsty. He tells the teacher, 'Can we stop for a minute, please?' The teacher shows the class a place in the shade. Sam sits down and takes his water bottle from his bag. His friend asks, 'Are you OK?' 'Yes, I am just tired,' he says. The teacher checks that everyone is ready before they continue. Sam walks more slowly for the rest of the trip. At school, he calls his father to say he is back.",
'How does Sam feel?|tired~Which part of his body hurts?|his feet~Where does the class stop?|in the shade',
'Nombra una sensación y una necesidad en una escena ficticia.|Pide ayuda o permiso para descansar con cortesía.|Escucha una instrucción sencilla y repítela con tus palabras.',
'Redacta un diálogo de ayuda: una persona explica qué siente y pide algo concreto; la otra confirma que entendió.')
add('a1',
'Was y were sitúan identidades, estados y lugares en el pasado. I/he/she/it combinan con was; you/we/they con were. La expresión temporal aclara el cambio: I am at home now, but I was at school yesterday. No añadas did a esta estructura.||Wasn’t y weren’t niegan; was/were delante del sujeto preguntan. Where were you? necesita un lugar; Were you at home? acepta una respuesta breve. Compara el sujeto de la pregunta con el de la respuesta, especialmente you/I.||Yesterday, last week y two days ago indican momentos terminados. Ago va después de una duración. Last no necesita the cuando significa la semana pasada. Antes de contar acciones completas, practica describir el escenario: dónde, cuándo y cómo estaban las personas.',
'Were you at home yesterday?|Did you were at home yesterday?|Con pasado de be, la pregunta se forma directamente con were.',
"Yesterday was my birthday. In the morning, I was at home with my family. The kitchen was full of food, and there were flowers on the table. My brother was not there at first because he was at work. At two o'clock, my friends were at the door. They had a small cake. I was very happy. The weather was warm, so we were in the garden in the afternoon. My brother was there later. At the end of the day, the house was quiet again. Today I am tired, but the photos are lovely.",
'What was yesterday?|the speaker’s birthday~Why wasn’t the brother there at first?|he was at work~Where were they in the afternoon?|in the garden',
'Describe dónde estabas ayer a tres horas distintas.|Compara cómo era un lugar ayer y cómo está hoy.|Haz dos preguntas y dos negaciones con was/were.',
'Escribe el escenario de un recuerdo en seis frases. Incluye personas, lugar, tiempo y estado de ánimo sin depender de una lista de acciones.')
add('a1',
'El pasado simple presenta acciones terminadas. Los regulares añaden -ed en escritura, pero la terminación no siempre es una sílaba extra. Los irregulares tienen formas propias: go/went, see/saw, buy/bought. Aprende los verbos dentro de una pequeña historia con un momento definido.||Después de didn’t vuelve al verbo básico: I didn’t go. Lo mismo ocurre en Did you go? No uses went después de did. Una respuesta breve usa did/didn’t; para dar más información puedes añadir la acción que sí ocurrió.||Ordenar los hechos ayuda a que alguien siga la historia: first, then, after that, finally. Mantén una línea temporal clara y añade un detalle de lugar o compañía. Revisa cada verbo, no solo el primero. Una narración corta puede comunicar mucho si el orden se entiende.',
'Did you see the film?|Did you saw the film?|Did ya marca pasado; el verbo principal es see.',
"Last Saturday, I visited my cousin. We wanted to go to the park, but it rained in the morning. We stayed at her house and made lunch. Then we watched a short film. In the afternoon, the rain stopped. We walked to the park and saw two friends there. We played a game and talked about school. I did not buy a snack because I had an apple in my bag. At six, I took the bus home. My cousin sent me a photo of the park. It was a simple day, but I enjoyed it.",
'Why did they stay at home in the morning?|it rained~Who did they see at the park?|two friends~How did the speaker go home?|by bus',
'Cuenta seis acciones de ayer con verbos regulares e irregulares.|Pregunta por dos detalles usando did.|Corrige una información con didn’t y explica lo que sí pasó.',
'Narra un día que cambió de plan. Usa al menos tres conectores, una negación y dos verbos irregulares.')
add('a1',
'Be going to + verbo básico comunica una intención o plan. Cambia am/is/are con el sujeto y conserva going to. Una hora o un día sitúa el plan. No confundas I am going to study con I am going to school: en el segundo ejemplo to introduce un destino.||Para preguntar mueve be: Are you going to cook? La respuesta puede ser breve y continuar con detalles. En la negación, not va después de be. Un plan puede cambiar: explica la alternativa en otra oración para mantener el mensaje sencillo.||Would you like to…? invita. Let’s + verbo propone una acción compartida. Aceptar incluye normalmente concretar lugar y hora; rechazar con amabilidad puede añadir una razón y otra opción. Una invitación no está resuelta hasta que ambos entienden el acuerdo.',
'She is going to visit us.|She going to visit us.|Going to necesita be; con she se usa is.',
"Nina is going to visit the town museum on Sunday. She sends a message to her friend. 'Would you like to come with me?' Her friend says, 'I'd love to, but I work on Sunday morning.' Nina asks if the afternoon is possible. They agree to meet at two thirty outside the museum. They are going to take the bus because the museum is far from home. Nina is going to bring some water. Her friend is going to check the ticket price. Before Sunday, they confirm the time again. They are both excited about the visit.",
'Where are they going?|the town museum~Why can’t the friend go in the morning?|the friend works~What time do they agree to meet?|two thirty',
'Explica tres planes con going to.|Invita a alguien y concreta hora y lugar.|Rechaza una primera hora y propone una alternativa.',
'Escribe un intercambio de mensajes que termine en un plan confirmado. Incluye una dificultad y su solución.')
add('a1',
'Un mensaje útil responde a un propósito: avisar, pedir, agradecer o invitar. Antes de escribir, decide qué debe saber la otra persona y qué esperas que haga. Pon el dato principal pronto. Una lista de oraciones correctas puede seguir siendo confusa si falta el lugar o la hora.||And añade, but contrasta, because da razón y so introduce un resultado. Evita encadenar todas las ideas con and. Dos frases cortas y claras pueden ser mejores que una frase muy larga. Revisa que cada parte tenga el sujeto y el verbo necesarios.||Lee buscando una tarea concreta: quién escribe, qué cambia y qué acción pide. Las palabras de fecha, cantidad y lugar pueden ser más importantes que conocer todos los adjetivos. En tu respuesta confirma los detalles que cambian y formula una pregunta si algo falta.',
'I am late because the bus is slow.|I am late so the bus is slow. [misma intención]|Because presenta la causa; so introduce un resultado.',
"Hi Emma, I am at the library, but I cannot stay until five. My brother needs help at home. Can we meet at four instead? The café next to the library is quiet, and we can study there for half an hour. Please bring your English notebook because I have a question about the homework. I have the class book, so you do not need yours. If four is not a good time, send me a message. I am going to leave the library at three fifty. Thanks, Jo. Emma reads the message and checks her afternoon plan before answering.",
'What new time does Jo suggest?|four~What should Emma bring?|her English notebook~Where does Jo suggest meeting?|the café next to the library',
'Resume el cambio principal de un mensaje.|Escribe una respuesta que confirme hora y material.|Une cuatro ideas con and, but, because y so.',
'Escribe una nota para cambiar una reunión: motivo, nueva hora, lugar y petición de confirmación. Léela como si no conocieras el contexto.')
add('a1',
'Una tarea final combina habilidades: presentarte, comprender datos, pedir algo y explicar un plan. Decide primero qué información necesitas para resolverla. Puedes tener dificultades y aun así comunicarte si sabes preguntar, confirmar y reformular con frases más sencillas.||Elige el tiempo por el significado: rutinas en simple, una acción actual en continuo, un hecho terminado en pasado y un plan con going to. No necesitas introducir todos en cada frase. Usa referencias temporales para ayudar a quien te escucha a seguir el cambio.||Comprueba tu autonomía con una segunda versión del proyecto: cambia ciudad, horario o acompañante y trabaja sin copiar el modelo. Conserva el primer borrador y compáralo con el nuevo. Una puntuación de ejercicios muestra práctica, pero la capacidad de usar el idioma se demuestra también en estas tareas abiertas.',
'Yesterday I visited the museum.|Yesterday I visit the museum. [relato terminado]|Yesterday sitúa la visita en el pasado; visited expresa la acción terminada.',
"My name is Ana, and I am in a new town for a short course. I stay with a friendly family. Every morning, I take the bus to school. Today I am walking because the weather is nice. Yesterday, I visited the market and bought some fruit. This afternoon, I am going to meet two students at a café. I do not know the café, so I ask my host for directions. It is opposite the bank. I check the time and take my notebook. I can use simple English to ask for help. I still make mistakes, but I can explain what I need.",
'Why is Ana walking today?|the weather is nice~What did she buy yesterday?|some fruit~Where is the café?|opposite the bank',
'Preséntate a una familia anfitriona y explica tu rutina.|Resuelve una compra o un trayecto con una pregunta de aclaración.|Cuenta algo de ayer y acuerda un plan para mañana.',
'Prepara tu aventura de dos días: presentación, plano, compra, recuerdo y plan. Graba una versión breve sin leer y escribe qué necesitas seguir practicando.')

# A2: relaciones entre hechos, alternativas y comunicación cotidiana sostenida.
add('a2',
'Una situación temporal puede durar semanas: I’m staying with my aunt this month no significa que en este segundo estés entrando en su casa. El presente simple presenta tu rutina general. Compara ambos desde la perspectiva del hablante, que decide si ve la situación como temporal o habitual.||La pregunta cambia con el tiempo: What do you do? puede preguntar por tu ocupación; What are you doing? por una actividad actual. Mantén el auxiliar correcto en las respuestas y añade frecuencia, compañía o lugar. Una respuesta ampliada permite que la otra persona continúe el intercambio.||Los verbos de estado suelen ir en simple: I know, I need, I prefer. Algunos tienen otro uso como actividad: I’m thinking about the problem. No decidas solo porque aparece now. Identifica si describes un conocimiento, una necesidad o una acción en desarrollo.',
'I need a quieter room.|I am needing a quieter room. [uso habitual]|Need suele expresar un estado y se usa normalmente en presente simple.',
"For most of the year, Carla works in a busy office. She usually takes the train and has lunch with her colleagues. This month, the office is being repaired, so she is working from her sister's flat. Her sister teaches in a school and leaves early. Carla likes the quiet mornings, but she misses talking to people during lunch. She is trying a new routine: she takes a short walk at twelve and calls a colleague afterwards. She does not want to work alone forever. For now, the arrangement is useful. On Fridays, the team meets at a café to discuss the week. Carla is learning that a small change can make a difficult situation easier.",
'Where is Carla working this month?|her sister’s flat~What does she miss?|talking to people during lunch~When does the team meet?|on Fridays',
'Explica tu rutina y dos cambios temporales.|Pregunta cómo se adapta otra persona a un horario nuevo.|Justifica qué parte del cambio te gusta y cuál no.',
'Escribe un mensaje comparando una semana normal con una excepcional. Incluye frecuencia, dos estados y una acción temporal.')
add('a2',
'Distingue apariencia y personalidad. What does she look like? pregunta por rasgos físicos; What is she like? puede preguntar cómo es como persona. What does she like? pregunta gustos. Aprende las tres preguntas como intercambios completos, porque una palabra pequeña cambia lo que se pide.||My acompaña a un sustantivo y mine lo sustituye: my jacket/the jacket is mine. Her/hers y their/theirs siguen la misma distinción. Whose pregunta por el dueño. Evita apóstrofos en yours, hers y theirs: ya son formas posesivas.||Una relativa breve identifica a alguien: the person who lives upstairs. That puede identificar cosas y también personas en relativas especificativas. No repitas el sujeto: the woman who works here, no who she works here. El detalle debe ayudar a distinguir al referente.',
'The blue bag is hers.|The blue bag is her.|Hers sustituye a her bag; her necesita un sustantivo detrás.',
"Two new neighbours moved into our building last month. Daniel is the man who lives on the second floor. He is tall, has curly hair and usually wears a dark jacket. His sister, Lina, is quieter, but she is very helpful. Yesterday, I found a bag near the entrance. I thought it was hers because she carries a similar one. I knocked on their door. Lina checked it and said, 'Mine is blue, but this one is green.' Daniel knew the owner: a student who lives upstairs. We left a note for her. Later, she thanked us and invited everyone for tea. A lost bag gave us a chance to learn more about our neighbours.",
'Where does Daniel live?|on the second floor~What colour is Lina’s bag?|blue~Who owns the green bag?|a student who lives upstairs',
'Describe a dos personas y compara aspecto con personalidad.|Resuelve de quién son cuatro objetos usando posesivos.|Identifica a una persona con una relativa breve.',
'Escribe un aviso de objeto encontrado sin revelar todos sus detalles. Añade preguntas para que quien lo reclame confirme que es suyo.')
add('a2',
'En una narración terminada, el pasado simple mantiene una secuencia principal. Los regulares y los irregulares comparten preguntas con did. Practica el significado junto a las formas; una lista de verbos no te enseña por sí sola a contar qué ocurrió y por qué fue importante.||Who called you? pregunta por el sujeto y normalmente no lleva did. Who did you call? pregunta por la persona que recibió tu llamada. En este segundo caso you ya es el sujeto. Compara las respuestas para distinguir las dos estructuras.||Then no explica causalidad por sí solo: ordena. Because explica el motivo; so, el resultado. En un relato breve, introduce situación, problema, acción y final. Selecciona detalles relevantes para quien escucha y no intentes mencionar todos los minutos del día.',
'Who called you yesterday?|Who did call you yesterday? [pregunta neutra por el sujeto]|Cuando who es el sujeto, la pregunta neutra no usa did; did puede aparecer con énfasis en otros contextos.',
"On our first day in Brighton, my brother and I decided to visit a small museum. We looked at a map and walked towards the centre. After twenty minutes, we arrived at a building with the right name, but it was a hotel. We checked the address again and discovered our mistake: there were two streets with similar names. A receptionist showed us the correct route. We took a bus and reached the museum before lunch. The tickets were cheaper than we expected, so we bought a guidebook too. That evening, we wrote the full addresses of the places we wanted to visit next. The mistake cost us some time, but we learned to check details more carefully.",
'What was the first building?|a hotel~How did they reach the museum?|by bus~What did they buy besides tickets?|a guidebook',
'Cuenta un error pequeño y cómo lo resolviste.|Haz preguntas por el sujeto y por el objeto de una acción.|Usa un conector temporal, uno de causa y uno de resultado.',
'Escribe una narración de 100–130 palabras con situación, problema, solución y aprendizaje. Revisa todos los verbos posteriores a did.')
add('a2',
'El pasado continuo dibuja una acción en desarrollo en un momento pasado. El simple presenta un hecho completo dentro del relato. I was cooking when the phone rang muestra un fondo y un acontecimiento; no afirma por sí solo cuánto duró la llamada o la comida.||While suele acompañar acciones en desarrollo y when puede introducir un momento o acontecimiento. No son botones automáticos que determinen el tiempo. Piensa si las acciones se superponen o si una ocurre durante la otra. Una línea temporal permite comprobarlo.||Was/were llevan la concordancia; el verbo principal lleva -ing. Para preguntas, Was she waiting? Para negaciones, they weren’t listening. Evita pasar todo el relato al continuo: los hechos que hacen avanzar la historia suelen ir en simple.',
'I was walking when I saw her.|I walking when I saw her.|La acción en desarrollo necesita was + -ing.',
"At about seven yesterday evening, our neighbours were preparing dinner. I was doing homework near the window, and my brother was looking for a charger. Suddenly, the lights went out. At first, we thought the problem was only in our flat. Then we looked outside and saw that the whole street was dark. My mother found a torch while my father checked the building's noticeboard. A neighbour was helping an older man on the stairs. We waited in the kitchen and talked instead of using our phones. The lights came back after half an hour. I finished my homework later, but I remembered the conversation more clearly than the television programme we had planned to watch.",
'What was the speaker doing?|homework~Who found a torch?|the mother~How long were the lights out?|half an hour',
'Describe qué hacían tres personas cuando ocurrió algo inesperado.|Dibuja una línea temporal para dos acciones simultáneas.|Haz una pregunta que aclare el contexto de la historia.',
'Cuenta un incidente con tres acciones de fondo y cuatro hechos principales. Explica qué cambió cuando terminó.')
add('a2',
'El presente perfecto conecta una experiencia pasada con el presente sin situarla necesariamente en una fecha terminada. Have/has + participio pregunta por tu experiencia hasta ahora. Si añades yesterday o in 2022 para ubicar el hecho, normalmente pasas al pasado simple.||Ever pregunta si algo ocurrió alguna vez; never dice que no ha ocurrido. Never ya es negativo: I have never tried it. Las respuestas breves conservan have/has. Para mantener una conversación, una pregunta general puede ir seguida de cuándo, dónde o con quién en pasado simple.||Been to suele indicar visita y regreso; gone to, que la persona ha ido y todavía no ha vuelto al punto de referencia. No es solo aprender dos traducciones: imagina dónde está la persona ahora. En experiencias usa participios correctos como seen, eaten y written.',
'Have you ever ridden a horse?|Have you ever rode a horse?|Después de have se necesita el participio ridden.',
"At the beginning of our travel club, the teacher asked about experiences. Most people had visited another city, but only a few had travelled alone. Mia said, 'I have never flown, but I have taken a night train.' We asked when she did that. She told us about a trip to her grandparents' town last winter. She slept badly, but she enjoyed watching the morning landscape. Her friend Paul has been to that town too, and he recommended a small museum. Another member could not join us because she has gone to Scotland for a course. We wrote three things we would like to try. I chose a night train because Mia's story made it sound interesting.",
'What has Mia never done?|flown~When did she take a night train?|last winter~Why is another member in Scotland?|for a course',
'Pregunta por cuatro experiencias sin fecha concreta.|Elige una respuesta afirmativa y pide detalles en pasado.|Explica si alguien ha vuelto de un lugar o todavía está allí.',
'Prepara una entrevista de experiencias. Empieza con Have you ever…? y continúa con al menos tres preguntas específicas en pasado simple.')
add('a2',
'Just destaca que algo pasó hace muy poco; already que ya ocurrió, a menudo antes de lo esperado; yet pregunta o niega que haya ocurrido hasta ahora. En los modelos del curso, just/already suelen ir entre have y el participio; yet al final de preguntas o negaciones.||For introduce duración: for two months. Since introduce el punto de inicio: since April. Si una situación continúa, el presente perfecto puede relacionar pasado y presente. No traduzcas llevo dos años viviendo como I have two years: expresa la duración de la situación.||Un momento terminado cambia el enfoque: I’ve lost my keys anuncia un resultado actual; I lost them yesterday sitúa el hecho. En algunas variedades, especialmente estadounidense, el pasado simple se usa más con just/already/yet. Reconoce la variación y practica de manera consistente.',
'I have lived here since March.|I have lived here for March.|Since introduce el punto de inicio; for introduce una duración.',
"Our community garden looks different this week. Volunteers have just put up a new sign, and they have already planted tomatoes in two areas. They have not finished the path yet because the ground is wet. Rosa has worked with the group since May. She joined after a neighbour invited her to a meeting. Before that, she had very little experience with plants. Now she knows which vegetables need more space. The group has used the same tools for three months, but one spade broke yesterday. They are going to repair it before buying another. Rosa says the best change is not the garden itself: she has met people she would never normally speak to.",
'What has the group not finished yet?|the path~When did Rosa join?|in May~What broke yesterday?|a spade',
'Da tres noticias recientes con just, already y yet.|Explica desde cuándo haces algo y durante cuánto tiempo.|Separa el resultado actual de un detalle pasado fechado.',
'Escribe una actualización de proyecto: terminado, pendiente y problema reciente. Incluye for, since y una fecha terminada.')
add('a2',
'Going to presenta una intención previa o una predicción apoyada en evidencia visible. Will sirve, entre otros usos, para decisiones tomadas al hablar, ofertas y predicciones generales. Un contexto puede admitir varias formas con matices distintos: no dependas solo de mañana como palabra clave.||El presente continuo puede indicar un acuerdo organizado: I’m meeting Jo at six. Añade detalles que muestren la organización. El presente simple aparece en horarios establecidos: the train leaves at eight. Distingue tus decisiones del funcionamiento programado de un servicio.||Una predicción no es una certeza. I think, probably y perhaps ayudan a mostrar tu grado de seguridad. Explica qué evidencia tienes y prepara una alternativa si el plan depende de otra cosa. El objetivo es comunicar el tipo de futuro, no llenar frases con will.',
'I’ll carry that bag for you.|I carry that bag for you. [oferta espontánea]|Will expresa aquí una oferta que surge al hablar.',
"We are organising a picnic for Saturday. I am meeting the group outside the station at ten; everyone has already agreed on the time. The train leaves at ten fifteen. We are going to buy food at a market near the park. When Jo says her bag is heavy, I offer to carry it. 'I'll take it,' I say. The forecast shows dark clouds in the afternoon, so we may need another plan. I think the morning will be dry, but we cannot be sure. We decide to check again on Friday. If the weather is bad, there is a covered market where we can still have lunch and spend time together.",
'Where is the group meeting?|outside the station~What time does the train leave?|ten fifteen~What is the alternative place?|a covered market',
'Distingue una intención, un acuerdo y una oferta espontánea.|Haz dos predicciones e indica tu grado de seguridad.|Explica un plan con horario y alternativa.',
'Diseña una salida y cuenta cómo surgió cada decisión. Usa cuatro formas de futuro según la situación, sin forzarlas en una sola frase.')
add('a2',
'Una invitación necesita actividad y, cuando sea posible, lugar y momento. Would you like to…? es directa y cortés; How about + -ing propone una posibilidad. Let’s + verbo invita a actuar juntos. Aprende la estructura que sigue a cada expresión.||Rechazar no implica cerrar la relación. Agradece, explica brevemente si quieres y ofrece otra fecha. I’d love to, but… mantiene un tono amable. No inventes una excusa complicada si basta con decir que no puedes. El significado y la cortesía dependen también del tono.||Al cambiar una cita, repite el dato nuevo y comprueba la disponibilidad. At six on Thursday combina hora y día. Si solo dices Thursday is fine puede quedar una hora antigua sin corregir. Termina con una confirmación que incluya los datos importantes.',
'How about meeting at six?|How about to meet at six?|Después de how about se usa habitualmente -ing.',
"I invited Ren to a film on Friday evening. He wanted to come, but he had to help at a family event. He suggested Saturday instead. I checked the cinema times and found a showing at six thirty. Ren asked if we could meet at six to get something to eat. That was too early for me because my swimming class ended at five forty-five. We agreed to meet outside the cinema at six fifteen and eat afterwards. On Saturday morning, Ren sent a message to confirm. I replied with the time and place. The exchange took several messages, but we both knew exactly what the final plan was.",
'Why couldn’t Ren go on Friday?|a family event~What time does the film start?|six thirty~When will they eat?|after the film',
'Invita usando dos estructuras distintas.|Rechaza la primera opción y ofrece otra.|Resume el acuerdo final tras dos cambios de horario.',
'Crea un intercambio de seis a diez mensajes con restricciones reales de horario. Termina con una confirmación inequívoca.')
add('a2',
'Un comparativo relaciona dos opciones: bigger than, more useful than. Un superlativo sitúa una dentro de un grupo: the cheapest of the three. Define el grupo antes de afirmar que algo es lo mejor. Better y worse son irregulares que conviene practicar por separado.||As…as expresa igualdad según una característica; not as…as indica menor grado. Más caro no implica mejor: separa el dato de tu opinión. Usa criterios comparables como distancia, precio, tamaño o facilidad, y aporta al menos un dato para sostener la comparación.||Than introduce el segundo elemento y the suele acompañar al superlativo. No combines more con -er. Algunas palabras de dos sílabas admiten variantes; céntrate en las frecuentes del nivel. Al decidir, relaciona la opción con tu necesidad, no solo con una etiqueta general.',
'This route is more convenient than that one.|This route is more convenient that that one.|Than introduce el segundo elemento de la comparación.',
"Our class needs a place for an end-of-term meeting. The park is the cheapest option because there is no entrance fee, but it has no roof if it rains. A café near school is more convenient than the park, although it is quite small. The community hall is the largest place and has a kitchen, but it costs more. We make a table with price, distance and space. For a group of twenty, the café is not big enough. The hall is not as close as the café, but everyone can reach it by bus. We choose the hall because we want a place that works in any weather. The best choice depends on our group.",
'Which option has no entrance fee?|the park~Why is the café unsuitable?|it is not big enough~Which place do they choose?|the community hall',
'Compara tres opciones con los mismos criterios.|Expresa una igualdad y una diferencia sin usar better.|Defiende una elección para una persona con necesidades concretas.',
'Prepara una tabla de tres lugares y escribe una recomendación de 100 palabras basada en sus ventajas y límites.')
add('a2',
'A few y a little indican una cantidad pequeña pero existente: a few eggs, a little oil. Few y little sin a suelen transmitir que la cantidad es escasa para lo esperado. El contexto cambia la valoración; no traduzcas ambas versiones como si fueran idénticas.||Too much y too many expresan exceso, no simplemente mucho. Enough expresa suficiencia: enough food, warm enough. Observa el orden según acompañe a un sustantivo o a un adjetivo. Una cantidad adecuada depende del propósito y de cuántas personas participen.||Las unidades convierten un incontable en cantidades manejables: two slices of bread, a bottle of milk. Al seguir una receta, diferencia los ingredientes disponibles de los necesarios. Una lista de compra se calcula a partir de esa diferencia y evita comprar por costumbre.',
'We have enough bread.|We have bread enough. [orden habitual]|Enough se coloca antes del sustantivo bread.',
"We planned lunch for six people, but two more friends decided to join us. There was enough rice, but we had only a few tomatoes and very little cheese. We did not want to buy too much food because several people were leaving the next day. We checked the cupboards and found some beans. My cousin suggested making a large salad and serving bread with it. We needed a little oil and two more tomatoes. At the shop, I almost bought a huge bottle of oil, but a smaller one was enough. Lunch was simple, and everyone had something they liked. Planning the quantities helped us spend less and leave very little food unused.",
'How many people came in total?|eight~What did they find in the cupboards?|beans~Why didn’t they want too much food?|several people were leaving the next day',
'Calcula cantidades para un grupo que cambia de tamaño.|Explica qué es suficiente, escaso o excesivo.|Transforma tres ingredientes incontables en unidades de compra.',
'Escribe una receta y una lista de compra para cuatro personas. Justifica dos decisiones de cantidad usando enough y too much/many.')
add('a2',
'One y ones sustituyen sustantivos contables ya conocidos: the red one, the smaller ones. No suelen sustituir directamente a sustantivos incontables como water. El contexto debe dejar claro qué objeto omites. Usa this/that one o these/those ones cuando la selección lo requiera.||Too small explica exceso de pequeñez; not big enough expresa insuficiencia de tamaño. El significado práctico puede ser parecido, pero el orden cambia: too + adjetivo; adjetivo + enough. Añade for me o to use para concretar el problema.||Una devolución se entiende mejor si explicas qué compraste, cuándo y cuál es el fallo. Después pide una solución concreta y escucha las condiciones. La actividad practica lenguaje de atención al cliente; las condiciones comerciales reales dependen de la tienda y del lugar.',
'These shoes are not comfortable enough.|These shoes are not enough comfortable.|Enough va después de un adjetivo.',
"I bought a small lamp for my desk, but the light was not bright enough for reading. I returned to the shop with the lamp and the receipt. The assistant asked what the problem was. I explained that it worked, but I needed a stronger light. She showed me two other lamps. The white one was brighter and had a movable arm. The black one was cheaper, but it was too tall for my shelf. I asked whether I could exchange my lamp and pay the difference. In this shop, that was possible. Before choosing, I checked the new lamp's size and tried the switch. This time, I knew which details mattered.",
'Why was the first lamp unsuitable?|it was not bright enough~Which lamp was too tall?|the black one~What did the customer bring with the lamp?|the receipt',
'Describe un problema con too o not…enough.|Compara alternativas usando one/ones.|Pide una solución y confirma sus condiciones.',
'Escribe un diálogo de devolución con explicación objetiva, petición y acuerdo. Incluye una pregunta antes de aceptar la alternativa.')
add('a2',
'Las preposiciones de movimiento describen un recorrido: through atraviesa un espacio, across cruza de un lado a otro, along sigue una línea y past pasa más allá de una referencia. Combínalas con un verbo concreto. En un plano, marca inicio y destino antes de seguir la descripción.||Where introduce una relativa de lugar: a café where you can study. No repitas there dentro de esa misma relativa. Puedes describir un lugar por su función aunque no conozcas su nombre: a place where I can print a document.||Para verificar indicaciones, reformula la parte dudosa: So I turn left after the bridge? Una pregunta específica permite una corrección rápida. Divide rutas largas en tramos y confirma referencias; repetir toda la ruta sin entender no demuestra que puedas seguirla.',
'It is a place where you can borrow books.|It is a place where you can borrow books there.|Where ya representa el lugar; there resulta redundante en esa relativa.',
"A visitor asked me for a place where she could print her ticket. I knew a copy shop near the river, but the usual bridge was closed. I explained another route. She needed to walk along the river, go through a small park and cross at the next bridge. The shop was just past the bank. She repeated the instructions but said 'before the bank'. I corrected that detail and pointed to the map. We also checked the shop's opening time on a sign nearby. The route was a little longer, but it avoided the closed bridge. Before leaving, she thanked me for explaining it in short steps instead of giving several street names at once.",
'What did the visitor need to print?|her ticket~Why was another route necessary?|the usual bridge was closed~Was the shop before or past the bank?|past the bank',
'Explica una ruta con cuatro preposiciones de movimiento.|Describe un servicio usando a place where…|Corrige un detalle que otra persona ha entendido mal.',
'Dibuja una ruta normal y otra alternativa por una calle cerrada. Explica ambas con referencias fáciles de verificar.')
add('a2',
'Los horarios oficiales suelen expresarse en presente simple: the train arrives at ten. Departure y arrival no son intercambiables. Aprende a localizar plataforma, destino y cambios antes de leer todos los detalles de un anuncio. El número de servicio puede ser más útil que la hora.||Un anuncio puede dar información en un orden distinto del esperado. Escucha una primera vez para identificar el servicio y otra para recoger el cambio. Delayed indica retraso y cancelled, cancelación. No adivines un número: pide que lo repitan o consulta el panel.||Al explicar un problema, incluye destino y conexión: I need to change at… Añade una pregunta concreta sobre la siguiente acción. Could you tell me which platform…? ayuda, pero una frase sencilla bien confirmada también puede resolver la necesidad.',
'The train leaves at eight.|The train is leave at eight.|Un horario se expresa aquí con presente simple; leaves concuerda con train.',
"We arrived at the station early for our train to York. The timetable said platform three, but an announcement mentioned a change. I heard the destination, although I missed the new platform number. Instead of following the crowd, I asked a member of staff. She said the train would leave from platform six and was ten minutes late. We had a connection in York, so I asked whether we still had enough time. She checked the next train and showed us the information on her screen. We moved to platform six and watched the departure board. The delay was small, but checking the change prevented us from waiting in the wrong place.",
'What was the original platform?|three~What was the new platform?|six~How late was the train?|ten minutes',
'Extrae destino, salida y plataforma de un anuncio.|Pide repetición de un número que no entendiste.|Explica una conexión y pregunta por una alternativa.',
'Crea un anuncio de cambio y un diálogo de consulta. Usa datos distintos de la lectura y comprueba que coincidan en ambos textos.')
add('a2',
'Can y could permiten pedir ayuda; could suele sonar menos directo. Would it be possible to…? añade distancia cortés. La cortesía también depende de incluir contexto y agradecer, no de usar la frase más larga. Pide una acción específica que la otra persona pueda realizar.||Distingue estado y funcionamiento: the room is cold describe una condición; the heater doesn’t work identifica un fallo. It isn’t working puede describir un problema actual. Aporta detalles observables y evita diagnósticos técnicos que no puedas comprobar.||Confirmar una reserva implica fechas de entrada y salida, personas, tipo de habitación y servicios relevantes. Two nights no significa necesariamente two days completos. Repite datos sensibles a malentendidos y anota qué solución te ofrece la recepción.',
'Could you check the heater, please?|Could you to check the heater, please?|Could se combina con el verbo básico sin to.',
"When we checked into the guesthouse, the receptionist confirmed our booking for two nights. We asked whether breakfast was included and what time it started. Upstairs, the room was clean, but the window did not close properly. The street was noisy, so sleeping with it open would be difficult. I called reception and explained the problem. I did not simply say that the room was bad; I described the window. A staff member came to check it. It could not be repaired that evening, so she offered another room at the back of the building. Before moving, we checked that the new room had two beds, as we had requested.",
'How many nights was the booking for?|two~What was wrong with the room?|the window did not close properly~Where was the replacement room?|at the back of the building',
'Confirma una reserva con cuatro datos.|Describe un problema observable y pide una acción.|Comprueba que la alternativa conserva lo que necesitas.',
'Escribe un intercambio en recepción con problema, dos preguntas y solución confirmada. Mantén un tono claro y cortés.')
add('a2',
'Para describir cómo te sientes, incluye el síntoma como lenguaje y el momento de inicio: I have a sore throat; it started yesterday. Distingue tired de tiring y hurt de pain en las expresiones aprendidas. No necesitas conocer palabras técnicas para explicar una necesidad.||Should/shouldn’t + verbo básico expresa consejo, no certeza ni obligación legal. Al practicar, usa situaciones cotidianas de estudio y descanso, y distingue una sugerencia de una instrucción profesional. Puedes pedir aclaración: What do you mean by…?||En una petición de ayuda, da información relevante y confirma la siguiente acción. Do I need to…? pregunta necesidad; Can I…? puede pedir permiso. Si no entiendes un término importante, no finjas comprender. Pedir que lo escriban también es una estrategia válida.',
'You should take a break.|You should to take a break.|Should lleva verbo básico sin to.',
"Before a long presentation, Emma felt tired and had a dry throat. She told her classmate that she had practised late the previous evening. Her classmate suggested taking a short break and checking that she had water. Emma decided to speak to the teacher about moving her presentation to a later time. She explained how she felt instead of only saying, 'I can't do it.' The teacher asked what would help and gave her a quieter place to wait. Emma also asked a friend to listen to her introduction once. This story is about communicating a need and asking for support, not about diagnosing a medical problem or choosing treatment.",
'What was Emma preparing for?|a presentation~Who did she ask about a later time?|the teacher~What did she ask a friend to listen to?|her introduction',
'Explica una necesidad de apoyo con contexto.|Da un consejo sobre preparar una exposición usando should.|Pide aclaración sobre una instrucción que no entendiste.',
'Escribe una petición de ayuda para una situación de estudio o trabajo. Indica el problema, lo que necesitas y una pregunta de confirmación.')
add('a2',
'Must y have to pueden expresar obligación. Have to se adapta a otros tiempos: had to, will have to. En preguntas cotidianas usa Do I have to…? La elección entre must y have to depende del contexto; no los reduzcas siempre a una oposición absoluta entre interno y externo.||Mustn’t prohíbe; don’t have to elimina la obligación. You don’t have to print it permite no imprimir, pero no lo prohíbe. Esta diferencia cambia decisiones reales. Al leer normas, identifica qué es obligatorio, qué está prohibido y qué es opcional.||Una regla se entiende mejor con alcance y motivo: quién debe hacer qué, dónde y cuándo. Ask before you… puede introducir un permiso. Para una situación ficticia, crea normas coherentes y pregunta por casos límite en lugar de memorizar frases aisladas.',
'You don’t have to bring lunch; it is provided.|You mustn’t bring lunch; it is provided. [sin prohibición]|No es necesario traer comida no equivale a prohibirla.',
"Our college opened a new study room. Students have to show their cards at the entrance, but they do not have to book a seat for ordinary use. Food is not allowed near the computers. The notice says students must not leave bags in the walkway. Small group discussions are possible in a separate area, where students can speak quietly. I wanted to use the printer, so I asked whether I had to bring my own paper. The assistant said paper was included, but colour printing cost extra. Reading the rules carefully helped me understand what was required and what was simply available as an option.",
'What must students show at the entrance?|their cards~Do students have to book an ordinary seat?|no~Where are small group discussions possible?|in a separate area',
'Clasifica seis normas como obligación, prohibición u opción.|Pregunta por un requisito y por un coste adicional.|Reescribe una prohibición para que no parezca opcional.',
'Crea las normas de una sala de estudio y un diálogo con tres preguntas de un usuario nuevo. Explica el motivo de dos reglas.')
add('a2',
'Can describe capacidad actual y could, capacidad general pasada. Para un logro concreto en una ocasión pasada se usa con frecuencia was/were able to o managed to, que se ampliará después. En A2, contrasta lo que sabías hacer antes con lo que puedes hacer ahora.||Can I…? pide permiso; Can you…? pide una acción. Borrow significa recibir algo prestado y lend, darlo prestado: Can I borrow your pen? Can you lend me your pen? Imagina la dirección del objeto para evitar confundirlos.||Los adverbios describen cómo se hace una acción: carefully, slowly, well. Good es adjetivo; well suele ser el adverbio correspondiente. No todos terminan en -ly: fast puede funcionar sin cambio. Relaciona modo y resultado con una tarea concreta.',
'She speaks clearly.|She speaks clear. [adverbio del curso]|Clearly describe cómo habla; clear puede describir una explicación o una voz.',
"When I started helping at the local club, I could use a computer, but I could not speak confidently to visitors. My first job was to show people where the rooms were. I spoke slowly and checked whether they understood. One day, a visitor needed to complete a form and had no pen. She asked, 'Can I borrow one?' I found a pen at the desk and asked her to return it afterwards. Over time, I learned to explain the booking process clearly. I can now answer common questions without looking at my notes. I still ask for help when a question is unusual, and that makes the service more reliable.",
'What was difficult at first?|speaking confidently to visitors~What did the visitor borrow?|a pen~What can the speaker now explain?|the booking process',
'Compara capacidades pasadas y actuales.|Pide permiso y solicita un objeto prestado con dos estructuras.|Describe cómo se realiza una tarea usando adverbios.',
'Escribe una breve historia de aprendizaje: punto de partida, práctica y capacidad actual. Incluye una petición de ayuda concreta.')
add('a2',
'El segundo verbo depende a menudo del primero: enjoy reading, want to read, decide to read. Aprende grupos completos y no una supuesta regla que sirva para todos. Después de una preposición, la forma -ing es frecuente: interested in learning.||Would like to expresa un deseo o una invitación; like + -ing suele hablar de gustos. Stop, remember y try pueden cambiar de significado según la estructura y se estudiarán con más detalle en B1. Por ahora, reconoce patrones frecuentes y comprueba los que no conoces.||Tomar una decisión requiere relacionar preferencias y condiciones. I’d prefer to… puede ir seguido de una razón; why don’t we…? propone una alternativa. Negocia duración, precio o dificultad y resume qué hará cada persona para convertir una preferencia en un plan.',
'I enjoy learning new songs.|I enjoy to learn new songs.|Enjoy se combina con -ing.',
"Three friends wanted to start a weekend activity together. Alex enjoyed working outdoors and suggested joining a gardening group. Bea preferred to learn something creative, so she wanted to try photography. Chen did not want to spend much money because he was saving for a course. They looked for an activity that could combine their interests. A community centre offered a free walk where people photographed local plants and helped identify them. They decided to try it once before making a regular commitment. After the walk, Bea enjoyed taking pictures, Alex liked being outside and Chen was pleased that the equipment was optional. Their choice worked because they discussed practical needs as well as preferences.",
'Who suggested gardening?|Alex~Why did Chen want a low-cost activity?|he was saving for a course~What did they decide to try?|a walk photographing local plants',
'Explica gustos con -ing y objetivos con to.|Propón tres actividades y negocia una.|Distingue una preferencia de una condición necesaria.',
'Escribe una conversación para elegir una actividad común. Incluye una objeción realista y una solución que responda a ella.')
add('a2',
'La primera condicional relaciona una condición posible con una consecuencia futura: If it rains, we’ll stay inside. La parte con if suele llevar presente, no will. Puedes poner la consecuencia primero sin cambiar la relación; la coma depende del orden.||When suele presentar algo esperado; if deja abierta la condición. En hábitos o hechos generales, ambas partes pueden ir en presente: If I miss breakfast, I feel hungry. Elige entre hábito y futuro concreto según el contexto, no solo la presencia de if.||May y might expresan posibilidad; no prometen un resultado. Añade una alternativa y explica qué dato falta para decidir. En situaciones de planificación, una condición útil tiene una acción concreta, un responsable y un momento para comprobarla.',
'If it rains, we will stay inside.|If it will rain, we will stay inside. [condición futura básica]|En esta estructura, la cláusula con if usa presente simple.',
"Our class is planning an outdoor exhibition. If the weather is dry, we will put the pictures in the courtyard. If it rains, we will use the main hall. The organiser says the hall may be busy until ten, so we might need to start later. We agree to check the room booking on Thursday. When visitors arrive, two students will welcome them and explain the route. Usually, if we give people a simple map, they find the rooms more easily. This time, we are also preparing signs. Having a second plan does not mean we expect everything to go wrong. It means we can respond without making every decision at the last minute.",
'Where will the exhibition be if it is dry?|in the courtyard~When will they check the room booking?|on Thursday~What helps visitors find the rooms?|a simple map',
'Formula tres planes condicionales con acciones concretas.|Separa una consecuencia habitual de una futura.|Expresa dos posibilidades sin tratarlas como certezas.',
'Crea un plan de evento con tres condiciones, dos alternativas y una fecha de revisión. Explica qué se sabe y qué falta confirmar.')
add('a2',
'To + verbo puede explicar finalidad: I went to the bank to ask a question. No uses for + verbo básico con esa misma función. For puede ir con sustantivo: for information. La finalidad responde para qué se hace una acción, no necesariamente por qué ocurrió.||En una pregunta indirecta, la parte introducida por where/when/what conserva orden de afirmación: Could you tell me where the office is? No where is the office. En sí/no usa if o whether. La pregunta exterior aporta la forma interrogativa.||Al hablar de dinero, separa precio inicial, coste periódico y cargos adicionales dentro del ejercicio. Pregunta qué incluye una cifra y cuándo se paga. No aceptes una cantidad sin entender si es por persona, por mes o por uso. Practica confirmar unidades y condiciones.',
'Could you tell me where the desk is?|Could you tell me where is the desk?|La pregunta indirecta usa sujeto + verbo: the desk is.',
"I visited the leisure centre to ask about a short swimming course. The poster showed a price of twenty pounds, but I did not know whether that was for one lesson or the whole course. At the desk, I asked the assistant to explain. The price covered four group lessons, while individual lessons cost more. I also asked whether I needed to buy special equipment. A swimming cap was required, but I could use my own. Before leaving, I wrote down the dates and the total cost. Comparing clear information was easier than choosing from the large number on the poster. I decided to check my timetable before booking.",
'Why did the speaker visit the centre?|to ask about a swimming course~How many group lessons did the price cover?|four~What equipment was required?|a swimming cap',
'Explica la finalidad de tres gestiones.|Pregunta indirectamente por lugar, coste y horario.|Confirma si un precio es total o por unidad.',
'Diseña una ficha de servicio y un diálogo para aclarar tres condiciones antes de contratarlo en la situación ficticia.')
add('a2',
'Someone/something se usan a menudo en afirmaciones; anyone/anything en preguntas y negaciones. Nobody/nothing ya contienen negación: Nothing works, no nothing doesn’t work con el mismo sentido. Estos pronombres suelen llevar verbo singular.||En turn it on, el pronombre va entre verbo y partícula. Con un sustantivo, turn on the screen y turn the screen on pueden funcionar. No todos los verbos compuestos son separables: aprende los del tema como unidades y observa los ejemplos.||Al explicar un fallo, distingue lo observado de lo supuesto. Describe el dispositivo, la acción y el resultado. Primero, después y finalmente ordenan una prueba. Una instrucción útil dice qué comprobar después de cada paso y qué hacer si el resultado no coincide.',
'Please turn it off.|Please turn off it.|Con este verbo separable, el pronombre it va en medio.',
"My grandmother wanted to join a video call, but she could not hear anything. I asked what she could see on the screen. The picture was clear, and the call was connected. Instead of telling her to press several buttons quickly, I gave one instruction at a time. First, we checked the volume. Then she noticed that a small headset was still connected to the computer. She unplugged it, and the sound returned through the speakers. Nothing was broken. After the call, we wrote a short guide with pictures of the controls. Next time, she could check the sound herself before asking for help. Explaining slowly made the task easier for both of us.",
'What was the problem?|she could not hear anything~What was still connected?|a headset~What did they create afterwards?|a short guide',
'Describe un fallo con algo observado y una duda.|Da cuatro instrucciones con pronombres bien colocados.|Confirma el resultado antes de pasar al siguiente paso.',
'Escribe una guía para resolver un problema cotidiano de tecnología. Incluye una comprobación tras cada instrucción, sin pedir datos privados.')
add('a2',
'Used to + verbo básico describe un hábito o estado pasado que contrasta con el presente. No sirve simplemente para una acción única fechada. En preguntas y negaciones con did, usa use to: Did you use to…? I didn’t use to… El cambio puede ser gradual.||Los adjetivos en -ed suelen describir a quien experimenta una emoción; los de -ing, lo que la provoca: bored/boring. Esta distinción no cubre todos los adjetivos ingleses, pero ayuda con los pares del tema. Identifica quién siente y qué provoca.||But, although y still conectan cambio y continuidad. Although introduce una oración completa. Still señala que algo continúa a pesar de una expectativa. Una comparación equilibrada explica qué mejoró y qué se mantiene difícil sin presentar todo el pasado como malo.',
'I used to live near the sea.|I use to lived near the sea.|Used to lleva el verbo básico live para un estado pasado.',
"When Luis was younger, he used to spend most evenings at home. He enjoyed films, but he rarely met people outside school. Last year, he joined a walking group. At first, he felt embarrassed because he did not know anyone. The long walks were tiring, although the conversations were interesting. Now he usually goes twice a month and sometimes helps plan the route. He still enjoys quiet evenings, so the change has not replaced everything in his life. He says he used to think a new hobby had to become a major commitment. Now he knows that a small, regular activity can be enough to meet people and learn about a place.",
'Where did Luis use to spend most evenings?|at home~How did he feel at first?|embarrassed~How often does he usually go now?|twice a month',
'Compara dos hábitos pasados con el presente.|Explica una emoción y qué la provoca.|Añade un aspecto que continúa usando still.',
'Escribe sobre un cambio pequeño y realista. Incluye used to, dos pares de emociones y una limitación que todavía existe.')
add('a2',
'Planificar un mensaje empieza por el lector: qué sabe ya, qué necesita saber y qué acción esperas. En una respuesta, cubre todos los puntos solicitados. Separa saludo, propósito, detalles y cierre sin convertir cada frase en un párrafo independiente.||Because da causa, so resultado y although contraste. Comprueba la lógica, no solo la gramática: un conector incorrecto puede invertir la relación entre ideas. En inglés, normalmente no combines although y but para unir las mismas dos cláusulas.||Revisar ocurre en dos pasadas. Primero comprueba contenido y orden; después verbos, pronombres, mayúsculas y puntuación. Leer en voz alta ayuda a detectar frases incompletas. Un modelo es una referencia, no la única respuesta válida: conserva tus propios detalles.',
'Although it was late, we continued.|Although it was late, but we continued.|En este patrón se usa although o but, no los dos para enlazar las mismas partes.',
"Hi Paula, thanks for offering to help with the book sale on Saturday. We are starting at ten in the school hall, but volunteers should arrive at nine thirty to arrange the tables. Please bring a bag for the books you want to donate. We already have enough boxes. You asked about lunch: the café will be closed, so bring something to eat. Although the sale ends at two, we will need another half hour to tidy up. Could you tell me whether you can stay until then? If you need to leave earlier, that is fine; I just need to organise the final tasks. Thanks again, Ravi.",
'What time should volunteers arrive?|nine thirty~Why should Paula bring lunch?|the café will be closed~What does Ravi need to know?|whether Paula can stay to tidy up',
'Extrae los puntos que una respuesta debe cubrir.|Redacta una respuesta con confirmación, restricción y pregunta.|Revisa primero el contenido y luego la forma.',
'Responde al mensaje con un horario diferente al de Paula. Cubre todos los puntos y explica una condición sin perder el tono amable.')
add('a2',
'En un proyecto integrado eliges formas conocidas para resolver una situación, no para demostrar todas las reglas a la vez. Usa pasado para un incidente, perfecto para experiencia y futuro para propuestas cuando esos significados sean necesarios. La claridad del mensaje guía la elección.||Una conversación sostenida incluye reacción y seguimiento. Muestra que escuchaste, añade un detalle y devuelve una pregunta. Si falta una palabra, descríbela por su función o por una categoría. Pedir aclaración es parte del desempeño, no señal de que la conversación haya fracasado.||Evalúa con evidencias: un texto propio, una explicación oral y una respuesta a una pregunta inesperada. Repite la tarea con datos diferentes después de unos días. El curso registra práctica; tu autoevaluación debe observar si puedes transferirla a una situación nueva con menos apoyo.',
'I have visited the town before. I went there last year.|I have visited the town last year.|La experiencia general puede ir en perfecto; last year requiere aquí pasado simple.',
"Our final class project is to plan a weekend for visitors who do not know the town. We have explored several places during the course, so everyone can suggest something. Last week, one group tested a walking route and found that a museum closed earlier than expected. We changed the plan and added a café nearby. We are going to prepare a timetable, a simple budget and an alternative for rain. Each student will answer a visitor's question without reading the full plan. I am responsible for transport information. I still need help with some words, but I can explain the main choices and ask the visitor to repeat a detail. The project brings separate lessons into one useful task.",
'Who is the weekend plan for?|visitors who do not know the town~What problem did the group discover?|the museum closed earlier than expected~What is the speaker responsible for?|transport information',
'Propón un fin de semana con presupuesto y restricciones.|Explica un incidente pasado que obligó a cambiar el plan.|Responde a una pregunta no preparada y confirma el acuerdo.',
'Entrega un itinerario, un mensaje a visitantes y una explicación oral de dos minutos. Cambia dos restricciones y adapta el proyecto sin copiar tu primera versión.')

# B1: razones, narraciones conectadas, precisión y adaptación a restricciones.
add('b1',
'El presente no se reduce a habitual frente a este segundo. El continuo también presenta cambios en desarrollo: more people are working remotely. El simple puede describir una situación que el hablante considera estable. Observa el marco temporal y qué contraste quiere destacar, no solo una palabra señal.||Think, have y see tienen usos distintos. I think it is useful expresa opinión; I’m thinking about changing jobs describe un proceso mental. I have a car expresa posesión; I’m having lunch describe una actividad. Construye pares con contexto para evitar prohibiciones demasiado generales.||Una respuesta desarrollada puede seguir idea, motivo, ejemplo y matiz. Un ejemplo concreto demuestra mejor la idea que repetir very o really. Termina reconociendo una excepción o una limitación relevante. Así puedes hablar con más detalle sin depender de frases artificialmente largas.',
'I think the plan is useful.|I am thinking the plan is useful. [opinión]|Think expresa aquí una opinión; thinking about presenta una actividad mental.',
"When our evening course changed its timetable, several students considered leaving. Most of us work during the day, and we depend on reliable transport. I normally travel with a colleague, but this month she is attending a different course. As a result, I am learning to organise my journey alone. At first, I thought the new arrangement would be impossible. Now I see that it has one advantage: I have half an hour in the library before class. I use that time to review notes rather than complete more exercises quickly. The change still creates difficulties on rainy evenings, when buses are crowded. I do not think every change is automatically positive. However, describing the specific problem has helped me look for a practical solution. Next week, two classmates and I are comparing our routes to see whether we can share part of the journey.",
'What does the speaker normally do?|travels with a colleague~How is the extra half hour used?|to review notes in the library~When are the buses crowded?|on rainy evenings',
'Describe una adaptación actual y el hábito que ha cambiado.|Desarrolla una opinión con motivo, ejemplo y limitación.|Haz una pregunta que distinga un estado de una actividad.',
'Escribe una reflexión de 140–180 palabras sobre un cambio. Explica una ventaja, una dificultad y una acción concreta, con ejemplos verificables dentro de tu relato.')
add('b1',
'Una historia conecta tres funciones: el simple hace avanzar hechos, el continuo da contexto y el past perfect sitúa algo antes de otro momento pasado. No necesitas usar past perfect en cada acción anterior si el orden ya resulta claro; úsalo cuando ayude a evitar ambigüedad.||Had + participio no cambia con el sujeto. La negación es hadn’t y la pregunta invierte had/sujeto. Compara When I arrived, they left con When I arrived, they had left: cambia si presenciaste su salida. Dibuja los dos órdenes antes de escribir.||Una narración eficaz introduce el problema, selecciona detalles y muestra una consecuencia. By the time destaca el límite temporal; while sitúa acciones paralelas. El cierre puede explicar qué aprendió el narrador sin añadir una moraleja obligatoria. Mantén referencias claras para he, she y they.',
'By the time we arrived, the shop had closed.|By the time we arrived, the shop has closed.|El punto de referencia es pasado; la acción anterior usa had closed.',
"We were travelling to a regional competition when we realised that one folder was missing. It contained the printed programme and several contact numbers. I had put it beside the door before leaving, but someone had moved it while clearing the table. At the station, our coach was buying tickets when I checked my bag. For a moment, we considered returning home. Then a teammate remembered that she had taken photos of the main pages the night before. We found a quiet corner and checked which information was still missing. The venue address and meeting time were clear, but one number was unreadable. Our coach called the organiser through the school office. We reached the venue on time, although we had to explain why we had no printed programme. The experience did not prove that paper was useless; it showed us why important plans need a second way to access essential information.",
'What was missing?|a folder~Who had photographed the pages?|a teammate~Which detail was unreadable?|one contact number',
'Ordena seis hechos en una línea temporal.|Cuenta el relato con contexto y un hecho anterior relevante.|Aclara un pronombre o una secuencia ambigua.',
'Escribe dos versiones de un incidente: orden cronológico y comienzo en el problema seguido de una explicación anterior. Comprueba que ambas cuentan los mismos hechos.')
add('b1',
'El perfecto no significa pasado reciente en todos los casos. Puede expresar una experiencia remota relevante ahora o una situación que sigue abierta. Un periodo como this week puede estar abierto para el hablante. El pasado simple enfoca un periodo terminado o un hecho situado dentro del relato.||For y since no obligan siempre al perfecto: I lived there for two years puede hablar de una estancia terminada. I have lived there for two years indica normalmente continuidad hasta ahora. Primero decide si la situación sigue vigente y luego elige la forma.||En una conversación, alterna preguntas generales y detalles. Have you worked with children? establece experiencia; What did you do in that role? pide hechos concretos. Evita perder la conexión con el propósito de la conversación: selecciona experiencias que ayuden a responder la pregunta actual.',
'I lived there for two years, but I moved away in June.|I have lived there for two years, but I moved away in June. [situación terminada]|La mudanza cierra la residencia descrita; lived expresa ese periodo terminado.',
"Our neighbourhood centre is looking for volunteers to organise a reading group. I have helped with events before, but I have never led a weekly activity. During an informal interview, the coordinator asks which tasks I have done. I explain that I worked at a book sale last spring and helped visitors choose books for different ages. She then asks what I did when someone could not find a suitable book. That question makes me describe a real situation instead of listing general qualities. I have also attended the centre's workshops for six months, so I understand how the rooms and booking system work. We agree that I will support an experienced volunteer first. My previous experience is useful, but it does not mean I already know every part of the new role. The conversation helps us identify both what I can contribute and what I still need to learn.",
'What has the applicant never done?|led a weekly activity~When was the book sale?|last spring~What will the applicant do first?|support an experienced volunteer',
'Relaciona una experiencia con una necesidad presente.|Pide detalles fechados después de una pregunta en perfecto.|Distingue una duración terminada de otra que continúa.',
'Prepara una entrevista de experiencia con tres ejemplos concretos y una habilidad pendiente. Usa los tiempos para mostrar qué sigue vigente y qué ocurrió en una fecha terminada.')
add('b1',
'Have/has been + -ing enfoca una actividad que se extiende hasta ahora o deja señales actuales. I’ve been running puede explicar por qué estás cansado aunque ya hayas parado. El perfecto simple suele destacar resultado o cantidad completada: I’ve run five kilometres.||How long suele dirigir la atención a duración; how many, a cantidad. Algunos verbos permiten ambas formas con poca diferencia y los de estado suelen preferir simple: I’ve known her for years. No uses continuo solo porque una actividad duró mucho. Decide qué quieres destacar.||Para explicar un problema, separa actividad, resultado y consecuencia. I’ve been trying to contact them, but I haven’t received a reply. Puedes haber realizado esfuerzo sin completar el objetivo. Este contraste es útil en actualizaciones de proyectos y peticiones de ayuda.',
'I have written three pages today.|I have been writing three pages today. [cantidad completada]|El perfecto simple destaca las tres páginas terminadas; el continuo enfoca la actividad.',
"For the last two weeks, our group has been preparing an audio guide to the town. We have recorded five short sections, but we have not finished the introduction. I have been editing the files in the evenings, and my eyes are tired. Another student has been checking the historical information because we do not want to repeat an attractive story as if it were a fact. Yesterday, we noticed that two sections used different names for the same building. We have now corrected both files. When the teacher asks about our progress, we explain what is complete and what is still taking time. Saying that we have been working hard would not give her enough information. We also need to identify the remaining tasks, the obstacle and the help we need. That makes the update useful for planning the next session.",
'How many sections have been recorded?|five~Why is another student checking information?|to avoid presenting an unverified story as fact~What inconsistency did they correct?|different names for the same building',
'Da una actualización que separe esfuerzo y resultado.|Pregunta por duración y por cantidad completada.|Explica un obstáculo y la ayuda que necesitas.',
'Escribe un informe breve de progreso con dos actividades continuadas, tres resultados y una tarea pendiente. No trates el esfuerzo como prueba de finalización.')
add('b1',
'Used to + verbo habla de una costumbre o estado anterior. Be used to + sustantivo/-ing significa estar acostumbrado; get used to describe el proceso de adaptación. En estas dos últimas estructuras, to es preposición, por eso puede seguirle -ing. No intercambies sus significados.||Would puede describir acciones repetidas del pasado cuando el contexto temporal está claro, pero no sustituye siempre a used to para estados: I used to live there. Introduce primero el periodo y luego los hábitos si usas would en una narración.||Al comparar etapas, distingue cambio objetivo y valoración personal. Antes viajabas menos: eso es un dato del relato. Que antes todo era mejor es una opinión que necesita contexto. Explica qué conservas, qué cambió y qué adaptación sigue en proceso.',
'I am getting used to working earlier.|I am getting used to work earlier.|En get used to, to es preposición y se usa working.',
"When I moved from a small town to the city, I expected the transport system to be the hardest change. I used to walk almost everywhere, and I rarely checked timetables. At first, taking two buses to college felt exhausting. After a few months, I got used to planning the journey, but I was still not used to the noise outside my window. I tried studying in several places before finding a quiet library. Now I appreciate being able to visit museums and meet classmates from different backgrounds. I still miss the short distances and familiar faces of my old town. The move has not made one place completely better than the other. It has changed which things are convenient and which require effort. I am still getting used to some parts of city life, and I no longer expect adaptation to happen all at once.",
'How did the speaker usually travel before?|on foot~What remained difficult after several months?|noise outside the window~Where did the speaker find a quiet study place?|a library',
'Contrasta hábito pasado, adaptación y costumbre actual.|Da una valoración equilibrada de dos etapas.|Explica qué sigue requiriendo esfuerzo.',
'Escribe una comparación de 150 palabras usando used to, be used to y get used to con significados distintos y ejemplos claros.')
add('b1',
'La elección de futuro comunica cómo entiende el hablante el evento: intención, decisión, acuerdo o horario. Dos formas pueden ser posibles con matices. En una conversación sobre organización, confirma los datos y la responsabilidad; una forma verbal correcta no resuelve un plan ambiguo.||Después de when, as soon as, before, after y until en cláusulas de tiempo futuro suele usarse presente: I’ll call when I arrive. La cláusula principal puede llevar will. Until marca hasta cuándo continúa algo; by indica un límite para terminarlo.||Un plan robusto explica qué depende de qué: cuando llegue el material, empezamos; si no llega, hacemos otra tarea. Distingue compromiso de predicción y avisa cuándo confirmarás lo incierto. El lenguaje de planificación debe permitir que otra persona sepa qué hacer después.',
'I will email you as soon as I arrive.|I will email you as soon as I will arrive.|La cláusula temporal con as soon as usa presente para este futuro.',
"We are organising a free workshop for new students. The room is booked for next Thursday, and two volunteers are meeting the trainer at the entrance. We are going to prepare printed instructions, but we will also keep a digital copy in case the printer fails. As soon as the trainer arrives, we will check the equipment together. I have offered to contact anyone who has not confirmed their place. The timetable says the building closes at seven, so we need to finish clearing up by six forty-five. One volunteer thinks attendance will be low because of another event nearby. That is a prediction, not a confirmed fact. We decide to review registrations on Tuesday before changing the room. Each person leaves the meeting with a task and a deadline. Knowing who will do what is more useful than simply saying that everything will be ready.",
'When is the workshop?|next Thursday~By what time must clearing up finish?|six forty-five~When will registrations be reviewed?|on Tuesday',
'Asigna tareas con responsables y plazos.|Distingue acuerdo, oferta y predicción en un plan.|Usa una cláusula temporal y una alternativa condicional.',
'Redacta un plan de preparación con cinco acciones, dependencias y fechas de comprobación. Señala qué está confirmado y qué es todavía una predicción.')
add('b1',
'La condicional cero describe relaciones habituales o generales; la primera, una posibilidad futura concreta. El resultado de una primera condicional puede usar will, un modal o un imperativo según la intención: If you need help, call me. No limites todas las respuestas a will.||Unless significa aproximadamente if not, pero reformular exige conservar la lógica: unless it rains equivale aquí a if it doesn’t rain. Evita negaciones dobles que inviertan la condición. Comprueba la frase con un ejemplo de lluvia y otro sin lluvia.||In case expresa preparación ante una posibilidad: take water in case the shop is closed. No esperas a confirmar el cierre para llevarla. If the shop is closed, buy water elsewhere plantea una acción condicionada. Dibuja cuándo sucede cada acción para distinguirlas.',
'Take a charger in case the battery runs out.|Take a charger if the battery runs out. [preparación previa]|In case indica que te preparas antes de saber si ocurrirá el problema.',
"Our hiking club sends a practical note before each walk. If the forecast includes severe weather, the organiser changes the route or cancels the event. Participants receive a message by seven in the morning. Unless they receive a change, they should meet at the usual station entrance. Everyone brings water in case the café on the route is closed. This is different from waiting until they find a closed café before deciding what to do. New members sometimes confuse the instructions, so the organiser gives examples. If the train is delayed, they should contact the group rather than run to catch up. The note also explains a general habit: if a member needs a slower pace, the group adjusts it. Clear conditions help people make decisions without having to guess which part of the plan still applies.",
'By when is a change communicated?|seven in the morning~Why do members bring water?|in case the café is closed~What should they do if the train is delayed?|contact the group',
'Distingue una norma habitual de una posibilidad concreta.|Reformula dos condiciones con unless sin cambiar su lógica.|Explica una preparación con in case.',
'Escribe instrucciones para una actividad con dos condiciones, una excepción y dos preparativos. Prueba las instrucciones imaginando tres escenarios diferentes.')
add('b1',
'La segunda condicional presenta una situación imaginaria o poco probable desde la perspectiva del hablante: If I had more time, I would study art. El pasado de la cláusula con if no sitúa necesariamente el hecho ayer. Contrástala con un futuro que sí ves posible.||Would + verbo describe el resultado; could destaca capacidad o posibilidad. If I were you es una fórmula frecuente para consejo. Were puede usarse con cualquier sujeto en situaciones hipotéticas, aunque was aparece en habla informal en algunos contextos.||Una hipótesis es útil para explorar prioridades: con más espacio, ¿qué cambiarías y por qué? Explica ventajas y límites. No confundas imaginar una solución con prometerla: si vuelves a un plan real, indica qué condiciones concretas tendrían que cumplirse.',
'If I had more time, I would practise daily.|If I would have more time, I would practise daily.|En la segunda condicional básica, if lleva pasado; would aparece en el resultado.',
"Our library asked visitors how they would improve the building if they had a small budget. Some people wanted more computers, while others preferred quiet study areas. I said that if I were responsible for the project, I would first ask which spaces were used most often. A larger reading room might help, but only if people could reach it easily. One student suggested longer opening hours. If the library stayed open later, she could study after work. The manager explained that staffing would be the main difficulty. We realised that every attractive idea had a practical limit. The discussion was still useful because it showed different priorities. We were not deciding what the library would definitely do; we were exploring possibilities before choosing a realistic proposal to investigate.",
'What would the speaker check first?|which spaces were used most often~Who would benefit from later hours?|a student who works~What was the main difficulty with later hours?|staffing',
'Explora tres cambios imaginarios y sus consecuencias.|Da consejo con If I were you y justifícalo.|Convierte una idea hipotética en una condición real a investigar.',
'Propón mejorar un espacio con presupuesto limitado. Compara dos hipótesis y explica cuál investigarías primero y qué información falta.')
add('b1',
'La fuerza de una expresión cambia la relación: must/have to obligan, should aconseja y can/may puede permitir. Needed to y had to sitúan necesidad u obligación en el pasado. Describe quién establece la regla y a quién se aplica cuando el contexto pueda resultar ambiguo.||Mustn’t y don’t have to siguen significando cosas distintas. Didn’t have to tampoco afirma que la acción no se hizo: solo dice que no era necesaria. Evita deducir un comportamiento únicamente a partir de la ausencia de obligación.||Un consejo razonado incluye objetivo, acción y motivo. Had better suele implicar una consecuencia negativa si no se sigue y puede sonar fuerte; no lo uses como sustituto neutro de toda sugerencia. Ajusta el tono al papel que tienes en la conversación.',
'We didn’t have to pay, but we chose to donate.|We didn’t have to pay, so paying was forbidden.|La ausencia de obligación no equivale a una prohibición.',
"Before starting a volunteer shift, everyone attended a short briefing. We had to sign in so the coordinator knew who was in the building. We were allowed to keep water bottles at the desk, but we could not leave personal bags in the entrance. We did not have to wear matching clothes; comfortable clothes were enough. The coordinator advised us to ask for help if a visitor became upset. She did not expect a new volunteer to solve every problem alone. Later, one member thought that not having to attend the optional afternoon session meant they were not allowed to attend. We clarified the difference. The session was available, but attendance was a choice. Explaining both the rule and its purpose made the instructions easier to remember and reduced unnecessary uncertainty during the shift.",
'Why did volunteers have to sign in?|so the coordinator knew who was in the building~Were matching clothes required?|no~What was the afternoon session?|optional',
'Explica reglas presentes y obligaciones pasadas.|Aclara una confusión entre prohibición y opción.|Da un consejo con motivo y tono adecuado.',
'Crea un documento de bienvenida con requisitos, opciones y recomendaciones. Añade un diálogo que resuelva una interpretación equivocada.')
add('b1',
'Must para deducción expresa una conclusión fuerte basada en indicios, no una obligación: she must be busy. Can’t expresa que algo parece incompatible con la evidencia. Ambos siguen siendo razonamientos del hablante; explica el indicio y evita presentarlo como observación directa.||May, might y could indican posibilidades. Una puerta cerrada puede tener varias explicaciones. Construye al menos dos hipótesis antes de elegir una y utiliza I’m not sure o it seems para marcar límites. No asignes porcentajes universales a cada modal.||La mejor continuación de una deducción suele ser una comprobación. Separa lo que viste, lo que piensas y cómo verificarlo. Esta distinción ayuda tanto al leer historias como al resolver malentendidos cotidianos sin acusar a alguien injustamente.',
'She might be in a meeting; I haven’t checked.|She must be in a meeting because I know nothing.|La falta de información no sostiene una deducción fuerte; might mantiene abierta la posibilidad.',
"When we arrived for rehearsal, the room was locked and the lights were off. One student said the teacher must have forgotten us. Another pointed out that there was a note on the door, although we could not read it from the corridor. We knew the rehearsal time because it was in our messages, but we did not know whether the location had changed. The teacher might be in another room, or the building staff might have locked the door by mistake. We walked closer and read the note. The rehearsal had moved upstairs because the floor was being cleaned. No one had forgotten the group. The incident showed how quickly a reasonable observation can become an unfair conclusion when we fail to separate evidence from explanation.",
'What did the students observe first?|a locked room with the lights off~Why had rehearsal moved?|the floor was being cleaned~Where was the new room?|upstairs',
'Da tres hipótesis distintas para una misma observación.|Separa evidencia, inferencia y comprobación.|Reformula una acusación como posibilidad pendiente de verificar.',
'Escribe una escena de malentendido con cuatro indicios. Presenta dos hipótesis plausibles y explica qué dato permite resolverlo.')
add('b1',
'La pasiva cambia el foco a quien recibe la acción: the bridge was repaired. Se forma con be en el tiempo adecuado y participio. La activa puede ser más clara cuando importa el responsable. Elige según la información que quieres destacar, no para hacer una frase más formal automáticamente.||By introduce al agente cuando aporta un dato necesario. With puede introducir una herramienta: painted with a brush. Si no sabes quién actuó o no es relevante, puedes omitir el agente sin inventarlo. Asegúrate de que el verbo admite la relación de objeto necesaria.||Al describir un proceso, divide fases y mantén una referencia temporal coherente. The paper is collected explica un procedimiento habitual; was collected describe una ocasión pasada. Un diagrama de pasos ayuda a comprobar que no falta una transformación entre inicio y resultado.',
'The forms are checked by a volunteer.|The forms are check by a volunteer.|La pasiva necesita participio: checked.',
"Our class visited a workshop where old bicycles are repaired and sold at low prices. First, each bicycle is checked for damage. Parts that cannot be used are removed, and suitable replacements are found. The brakes and tyres are tested before the bicycle is cleaned. A volunteer explained that not every bicycle can be repaired economically. Some are used as a source of parts instead. Last month, twenty bicycles were prepared for new owners. We asked who was responsible for the final safety check because that stage mattered more to us than the colour of the frame. The answer identified a trained mechanic. Describing the process in the passive helped us follow what happened to the bicycle, while naming the mechanic clarified responsibility at a key point.",
'What happens first?|each bicycle is checked for damage~How many bicycles were prepared last month?|twenty~Who performs the final safety check?|a trained mechanic',
'Transforma una descripción para cambiar el foco sin perder información.|Explica un proceso habitual y una ocasión pasada.|Decide cuándo importa nombrar al agente.',
'Describe un proceso de cinco pasos con entrada, transformación y resultado. Incluye una frase activa donde identificar al responsable sea útil.')
add('b1',
'Transmitir un mensaje requiere conservar su significado y ajustar perspectiva. Si el verbo introductor está en pasado, suele haber cambios como am a was y will a would. Si la información sigue vigente, el retroceso no siempre es obligatorio. El contexto decide cuánto cambia, no una tabla aplicada sin pensar.||Say no lleva directamente persona sin to; tell suele llevar destinatario: she told me. En preguntas indirectas se usa orden de afirmación: he asked where I lived. En preguntas de sí/no aparece if/whether. No mantengas do/does/did como auxiliar de pregunta.||Los pronombres y expresiones como here, tomorrow o this dependen del lugar y momento del nuevo relato. Relee el mensaje como si lo recibiera alguien que no estuvo presente. Una petición se puede transmitir con asked + persona + to + verbo.',
'He asked where I lived.|He asked where did I live.|La pregunta transmitida usa orden de afirmación, sin did interrogativo.',
"After a planning meeting, I had to send the decisions to a classmate who was absent. During the meeting, the organiser said, 'We will start at nine tomorrow.' Because I was writing that evening, I could still say that the event would start at nine the next day. I also explained that the organiser had asked everyone to bring a reusable cup. One volunteer had asked whether parking was available, and the answer was no. When I drafted the message, I noticed that I had written 'here' without saying which building I meant. I replaced it with the venue name. Reporting speech was not only an exercise in changing verb forms. I had to make sure that times, places and people were clear from my classmate's point of view.",
'Who was the message for?|an absent classmate~What should everyone bring?|a reusable cup~Why did the writer replace here?|the building was unclear',
'Transmite una afirmación, una pregunta y una petición.|Ajusta pronombres y tiempo según quién recibe el mensaje.|Detecta una referencia de lugar que resulte ambigua.',
'Redacta notas de una reunión y luego un mensaje para alguien ausente dos días después. Revisa especialmente fechas, tomorrow y here.')
add('b1',
'Una relativa especificativa identifica: the student who borrowed my book. Una explicativa añade información sobre un referente ya identificado y se separa con comas. En las explicativas no se usa that. La puntuación puede cambiar qué personas incluye una afirmación.||Whose expresa posesión; where, lugar. Who/which pueden funcionar como sujeto u objeto dentro de la relativa. En algunas especificativas puede omitirse el relativo cuando es objeto: the book I bought. Si es sujeto, no lo omitas: the person who called.||Más detalle no siempre da más precisión. Elige la característica que distingue realmente al referente y elimina repeticiones. Comprueba que la relativa se une al sustantivo correcto, especialmente si hay varios nombres seguidos. Lee la frase sin la relativa para entender qué información añade.',
'The woman whose bike was stolen called us.|The woman who her bike was stolen called us.|Whose expresa la relación posesiva entre la mujer y la bicicleta.',
"We are creating a guide to useful places for new residents. The first draft listed 'the shop near the station', but there are several shops there. We changed the description to 'the shop that repairs phones and stays open until seven'. That detail identifies the right place. We also included the library, which has a free study room on the first floor. The extra information is useful, but residents already know which library we mean. One volunteer interviewed a neighbour whose family has run a bakery for thirty years. Her story added local context. While editing, we removed a long relative clause that described the wrong building because it followed an unclear noun. Our goal was not to make every sentence longer. It was to give enough relevant information for a newcomer to find the place without guessing.",
'What identifies the correct shop?|it repairs phones and stays open until seven~Where is the library study room?|on the first floor~How long has the family run the bakery?|thirty years',
'Identifica un lugar con una relativa necesaria.|Añade un dato explicativo con puntuación adecuada.|Describe una relación de posesión con whose.',
'Escribe una guía de cinco personas o lugares. Usa relativas para resolver ambigüedades reales y elimina las que no aporten información útil.')
add('b1',
'Aprender patrones verbales implica forma y significado: avoid doing, decide to do, allow someone to do. Algunos verbos admiten las dos formas con matices; otros no. Registra el verbo junto con un ejemplo propio para recordar qué estructura completa necesita.||Remember to call es recordar una acción pendiente; remember calling es recordar una acción pasada. Stop smoking termina la actividad; stop to smoke interrumpe otra para hacerla. Try doing prueba un método; try to do intenta lograr una acción. El contexto debe hacer visible la diferencia.||Después de preposición suele aparecer -ing: interested in learning, good at explaining. La finalidad suele expresarse con to + verbo. No decidas por ver la palabra to: en look forward to, to es preposición. Consulta y practica la expresión completa cuando sea nueva.',
'Remember to send the form before Friday.|Remember sending the form before Friday. [recordatorio de una tarea pendiente]|To send señala una acción que todavía debe realizarse.',
"While preparing a community exhibition, I learned how much small verb patterns can change a message. I asked a friend to remember to collect the keys, but he thought I was asking whether he remembered collecting them the previous week. We clarified the date. Later, I stopped writing labels to answer the phone; I did not stop writing labels permanently. Another volunteer suggested trying a larger font because visitors might find the small text difficult to read. We tested one label before changing them all. At the end, we avoided adding too much information to each display. The work gave us practical reasons to choose one structure instead of another. Studying the verbs in a list had helped us recognise them, but explaining actual actions made the differences easier to remember.",
'What task concerned the keys?|collecting them~Why did the writer stop writing labels?|to answer the phone~What change did they test on one label?|a larger font',
'Explica pares que cambian de significado con -ing o to.|Describe una prueba de método y un intento de logro.|Redacta recordatorios inequívocos para tareas pendientes.',
'Crea tres pares de miniescenas con remember, stop y try. Demuestra con contexto por qué cada estructura comunica algo diferente.')
add('b1',
'Much, far y a lot pueden intensificar comparativos; slightly y a little indican diferencias pequeñas. Very no suele modificar directamente better en el patrón habitual. Un dato numérico ayuda a que mucho o poco no dependa solo de una impresión.||Too expresa exceso respecto a un fin; enough, suficiencia. Too expensive for us y expensive no significan lo mismo. As…as compara igualdad y not nearly as…as marca diferencia amplia. Conserva el mismo criterio y la misma unidad al comparar opciones.||Una recomendación distingue requisitos de preferencias. Un lugar más barato puede fallar en accesibilidad; uno más grande puede quedar lejos. Explica el intercambio entre ventajas y límites y di para quién recomendarías cada opción. No conviertas una preferencia personal en clasificación universal.',
'The new route is much faster.|The new route is very faster.|Much puede modificar un comparativo como faster; very no en este patrón.',
"Our group compared three venues for a training day. The first was much cheaper than the others, but it was too small for practical activities. The second was slightly farther from the station and had enough space, although its entrance had several steps. The third cost more but was easier to reach and included the equipment we needed. Instead of choosing the cheapest price immediately, we listed essential requirements and optional advantages. Accessibility was essential because all participants needed to use the same room. A large garden was pleasant but unnecessary. We recommended the third venue for this event, while noting that the first could suit a smaller group. The recommendation became more convincing when we explained which needs each option met, rather than describing one place as simply 'the best'.",
'Why was the cheapest venue unsuitable?|it was too small~Which requirement was essential?|accessibility~For whom might the first venue work?|a smaller group',
'Compara diferencias grandes y pequeñas con datos.|Distingue requisitos de preferencias.|Recomienda opciones distintas para públicos distintos.',
'Elabora una comparación de tres servicios con cuatro criterios. Escribe una recomendación condicionada al usuario y explica al menos una desventaja de tu elección.')
add('b1',
'Little/few pueden expresar escasez; a little/a few, una cantidad pequeña disponible. Most describe la mayoría y most of se usa antes de un grupo determinado: most students, most of these students. La referencia del sustantivo decide la estructura.||Each destaca individuos y every considera el conjunto distribuido. Both, either y neither se usan con dos opciones en los patrones básicos. Practica qué grupo describes y qué elementos incluye la afirmación. Evita usar estos cuantificadores sin un referente claro.||Al distribuir recursos, expresa total, uso y resto. Enough para una tarea puede ser insuficiente para otra. Separa materiales contables de recursos incontables como time, information o equipment. Si necesitas contar, usa pieces of equipment o items, según el contexto.',
'We need more information.|We need more informations.|Information se usa normalmente como incontable; no añade -s.',
"A local club received a small donation for learning materials. Most members wanted new books, but a few asked for better lighting in the study area. The committee had little money left after paying the room costs, so it could not do everything at once. Each member suggested one priority and explained who would benefit. Both proposed lamps were suitable, but neither included a replacement bulb. That detail changed the total cost. The group also realised that it already had enough books for beginner sessions, although it lacked suitable texts for more confident readers. They bought one lamp and a limited set of intermediate books. The decision was based on the available resources and the needs of different members. It was not a perfect solution, but everyone could see how the money had been allocated.",
'What did a few members request?|better lighting~What did neither lamp include?|a replacement bulb~Which reading level needed more suitable texts?|intermediate',
'Explica cómo distribuyes un recurso limitado.|Contrasta la mayoría con grupos pequeños.|Describe dos alternativas usando both, either o neither.',
'Diseña un presupuesto ficticio y justifica tres prioridades. Usa cuantificadores con referencias claras y distingue cantidades de suficiencia para una tarea.')
add('b1',
'Because introduce una cláusula con sujeto y verbo; because of, un grupo nominal. Although también necesita una cláusula, mientras despite/in spite of suelen ir con nombre o -ing. Mantener la misma relación lógica puede requerir cambiar la estructura que sigue al conector.||However conecta ideas en contraste y necesita puntuación adecuada. No sustituye mecánicamente a but dentro de cualquier oración. Por eso conviene escribir primero las ideas simples y después elegir el enlace que expresa mejor causa, consecuencia, contraste o ejemplo.||Un párrafo desarrolla una idea central con explicación y evidencia. Una frase inicial orienta, los ejemplos la sostienen y un cierre puede matizarla. Si cada frase introduce otro tema, quizá necesitas reorganizar o dividir. Revisa también referencias como this y it: deben tener antecedente claro.',
'The event continued despite the rain.|The event continued despite it rained.|Despite lleva aquí un grupo nominal; although admitiría it rained.',
"Some classmates believe all group work should happen online because it saves travel time. I understand that advantage, especially for students who live far from the centre. However, our recent project showed that the best arrangement may depend on the task. We shared documents online and completed simple edits quickly. When we needed to solve a disagreement about the project's purpose, a face-to-face discussion was more effective. Despite the extra journey, that meeting saved time later because everyone understood the decision. This does not mean online communication is unsuitable for difficult conversations. It means our group needed a clearer structure for them. Next time, we plan to send an agenda before the call and allow each person to explain their view. A useful conclusion should connect the evidence to the proposal rather than repeat the opening opinion with stronger language.",
'What online task was completed quickly?|simple document edits~What issue benefited from meeting in person?|a disagreement about the project’s purpose~What will they send before the next call?|an agenda',
'Une las mismas ideas con because y because of cambiando la estructura.|Organiza un párrafo con idea, ejemplo y matiz.|Revisa referentes ambiguos y conectores redundantes.',
'Escribe dos párrafos sobre una decisión cotidiana. Incluye una objeción razonable y responde con evidencia de una experiencia concreta.')
add('b1',
'Las preguntas indirectas mantienen orden declarativo en la parte interna: Do you know when the next train leaves? La pregunta exterior ya lleva el auxiliar. En sí/no, if/whether evita inventar una palabra interrogativa. La cortesía funciona mejor cuando la pregunta es concreta.||Describir un contratiempo requiere situación, problema y consecuencia: el tren se canceló y perderás una conexión. Separa esos hechos de tu petición. Puede que haya varias soluciones aceptables; indica la restricción importante, como llegar antes de una hora, para facilitar una alternativa.||Antes de aceptar, confirma ruta, tiempo, coste y siguiente paso relevantes. So, just to check… resume. Pedir que un nombre se escriba o que una instrucción se repita evita errores. Una solución no está clara hasta que puedes explicarla con tus propias palabras.',
'Could you tell me whether this ticket is valid?|Could you tell me is this ticket valid?|Una pregunta indirecta de sí/no introduce whether o if y usa orden declarativo.',
"On the way to a training course, I discovered that my connecting bus had been cancelled. The information board suggested another route, but it was not clear whether my ticket would be accepted. At the desk, I explained my destination and the time by which I needed to arrive. I asked whether there was an alternative that avoided a long walk with my bag. The assistant proposed a train followed by a short local bus journey. Before agreeing, I checked the total travel time and asked her to write down the name of the stop. I then summarised the route to make sure I had understood. I arrived later than originally planned but before the course began. The useful part of the conversation was not using complicated language; it was making my priorities clear and confirming each practical detail.",
'What had been cancelled?|the connecting bus~Which physical constraint did the traveller mention?|avoiding a long walk with a bag~What did the assistant write down?|the name of the stop',
'Explica un contratiempo y la consecuencia que más importa.|Pide información mediante preguntas indirectas.|Resume una alternativa antes de aceptarla.',
'Representa una reclamación de viaje con dos soluciones posibles. Elige una según restricciones y confirma todos los datos necesarios para actuar.')
add('b1',
'Una reclamación clara distingue descripción y juicio. The handle broke after two days aporta un hecho; the product is terrible expresa una valoración. Empieza con el hecho, añade contexto suficiente y explica cómo te afecta. Conserva un tono que permita discutir una solución.||Would you be able to…? y I would appreciate… formulan peticiones. La cortesía no exige ocultar lo que necesitas. Propón una solución concreta y pregunta por el procedimiento. En tareas ficticias, evita afirmar derechos legales o condiciones comerciales que no se hayan dado en el escenario.||Al negociar una solución, escucha restricciones y confirma compromisos. Who will contact whom, by when? debe quedar claro. Un correo de seguimiento puede resumir el acuerdo. Diferencia una propuesta de algo confirmado para no dar por cerrado un asunto que sigue pendiente.',
'I would appreciate a replacement.|I would appreciate if a replacement. [oración incompleta]|Appreciate puede llevar un grupo nominal; otra opción es I would appreciate it if you could…',
"I ordered a desk organiser for a shared study room. The parcel arrived on time, but one section was cracked. I wrote to the seller with the order number and a clear description of the damage. Rather than saying that the whole service was useless, I explained that the broken section could not hold books safely. I asked whether they could replace that part instead of sending an entirely new organiser. The first reply offered a discount, but that would not solve the practical problem. I explained this and asked about another option. The seller then proposed sending a replacement section the following week. I replied to confirm the delivery address and asked them to tell me when it had been dispatched. The exchange stayed focused on the fault, the effect and the agreed next step.",
'What was wrong with the organiser?|one section was cracked~Why was a discount insufficient?|it did not solve the practical problem~What solution was agreed?|a replacement section',
'Transforma una queja vaga en una descripción observable.|Pide una solución específica con tono cortés.|Rechaza una propuesta insuficiente explicando por qué.',
'Escribe una reclamación y una respuesta de seguimiento. Incluye hechos, efecto, solución propuesta y confirmación del compromiso final.')
add('b1',
'Una candidatura gana claridad cuando las habilidades tienen ejemplos. I am organised es general; explicar cómo coordinaste turnos muestra una conducta. No necesitas experiencia profesional para usar ejemplos de estudio o proyectos personales, pero distingue experiencia real de práctica o interés.||Para responder, sitúa la tarea, describe tu acción y explica el resultado. Evita atribuirte todo el trabajo de un grupo. El pasado cuenta un ejemplo concreto; el perfecto puede resumir experiencia relevante hasta ahora. Añade qué aprendiste cuando el resultado no fue perfecto.||Un objetivo creíble relaciona puesto, interés y siguiente aprendizaje. Preguntar por tareas, formación y expectativas también demuestra comprensión del rol. Prepara ideas, no un discurso invariable: escucha la pregunta exacta y adapta la extensión de tu respuesta.',
'I helped organise the event and managed the sign-in desk.|I organised everything. [cuando solo hiciste una parte]|Una respuesta precisa delimita tu contribución y aporta evidencia sin exagerarla.',
"I applied to help at a summer learning centre. The form asked about organisation and communication, so I described a class project rather than simply listing positive adjectives. During that project, I kept track of deadlines and reminded group members about missing information. I also admitted that our first plan was too ambitious and explained how we reduced the number of activities. At the interview, the coordinator asked what I would do if a visitor asked a question I could not answer. I said I would explain that I needed to check, find the right person and make sure the visitor received a response. I had not done exactly the same job before, but I could connect my experience to its tasks. Before leaving, I asked what training new helpers received and how their first week was organised.",
'What experience did the applicant use?|a class project~What was wrong with the first plan?|it was too ambitious~What did the applicant ask about at the end?|training and the first week',
'Sostén una habilidad con un ejemplo concreto.|Explica tu contribución dentro de un trabajo compartido.|Responde a una pregunta inesperada y formula otra sobre el puesto.',
'Prepara una presentación profesional de 90 segundos y un correo de candidatura. Incluye dos evidencias, una limitación y un objetivo de aprendizaje realista.')
add('b1',
'According to… atribuye una afirmación a una fuente; no demuestra por sí solo que sea cierta. The article says… separa la voz del autor de la tuya. Al resumir, conserva límites como may, some o in this sample; eliminarlos puede volver más fuerte una conclusión de lo que era.||Verificar implica preguntar quién publica, cuándo, con qué evidencia y si otras fuentes independientes coinciden. Una imagen o un título no reemplaza el texto completo. Diferencia fecha del hecho y fecha de publicación cuando un contenido antiguo reaparece.||Al admitir incertidumbre, explica qué parte no está confirmada y qué comprobarías. I haven’t verified the date es más útil que una duda vaga sobre todo. Resume la información necesaria para tu lector sin copiar largas frases de la fuente ni introducir detalles que no estaban.',
'According to the report, some participants improved.|The report proves everyone improved. [misma evidencia]|Some no equivale a everyone y reportar un resultado limitado no justifica esa generalización.',
"A message in our class group claimed that the town library was closing permanently. The headline looked serious, and several people shared it without opening the link. I read the article and noticed that it described a temporary closure for repairs two years earlier. The publication date was old, and the photograph showed the building before its renovation. I checked the library's own current notice and found normal opening hours with one room temporarily unavailable. I posted a short correction that explained the dates and linked to the relevant notice. I did not accuse classmates of deliberately spreading false information; the old headline was easy to misunderstand. The experience reminded us that a source can be real while a new interpretation of it is misleading. We agreed to check dates and read beyond headlines before sharing practical information.",
'What did the shared message claim?|the library was closing permanently~What did the old article actually describe?|a temporary closure for repairs~What was currently unavailable?|one room',
'Resume una afirmación atribuyéndola a su fuente.|Identifica un límite que no debe desaparecer al resumir.|Escribe una corrección clara y respetuosa.',
'Crea dos versiones de un resumen: una que exagera y otra fiel a una evidencia ficticia. Explica los cambios de alcance, fecha y certeza.')
add('b1',
'Una sugerencia útil nombra acción y propósito. We could… abre una posibilidad; why don’t we…? invita a considerarla. Would it be worth…? puede explorar valor. No confundas falta de respuesta con acuerdo: pregunta qué piensa quien aún no ha hablado.||Discrepar con una razón concreta mantiene el foco en la propuesta: I see the advantage, but I’m concerned about… Reconocer una ventaja no obliga a aceptar toda la idea. Ofrece una alternativa que responda al mismo objetivo en lugar de limitarte a rechazar.||Cerrar un acuerdo implica resumir decisión, responsables y revisión. Un punto pendiente debe quedar como pendiente. Puedes registrar desacuerdo sin bloquear una prueba pequeña: try it for a week and review. La colaboración se demuestra tanto escuchando como hablando.',
'I agree with your suggestion.|I am agree with your suggestion.|Agree funciona como verbo; no necesita be en esta afirmación.',
"Our study group disagreed about how to prepare for a presentation. One member wanted everyone to memorise a full script. Another preferred speaking from a few notes. I could see why a script felt safer, but I was worried that we would struggle if someone asked an unexpected question. Instead of voting immediately, we tested both approaches with a short section. The notes sounded more natural, although we sometimes missed important details. We agreed to prepare a shared outline with essential facts and practise answering questions separately. Each person took responsibility for checking one section. We also set a time to review the whole presentation together. Not everyone preferred the final method, but everyone understood why we chose it and what they needed to do next. The disagreement helped us identify the real need: accuracy with enough flexibility to respond.",
'What were the two approaches?|a full script and brief notes~What problem appeared with notes?|missing important details~What did they finally prepare?|a shared outline with essential facts',
'Discrepa reconociendo una ventaja real.|Propón una prueba que ayude a decidir.|Resume un acuerdo con tareas y asuntos pendientes.',
'Redacta un diálogo de reunión con tres puntos de vista. Evita que todos acepten enseguida y termina con un compromiso concreto y revisable.')
add('b1',
'Una reseña distingue descripción de reacción. Describe género, formato, actividad o servicio y luego explica tu experiencia con ejemplos. Interesting por sí solo informa poco; decir qué parte mantuvo tu atención permite que otra persona valore si comparte tu gusto.||Recommend puede ir con -ing o con that + cláusula en patrones frecuentes. I recommend visiting… es una opción segura. Worth también suele llevar -ing. Avoid I recommend you to… en los modelos del curso; usa I recommend that you… o I’d recommend… según el contexto.||Una recomendación responsable tiene público y límites. Un libro adecuado para lectores pacientes puede resultar lento a quien busca acción. Indica nivel de apoyo, tiempo o intereses necesarios y evita generalizar una sola experiencia como garantía. La utilidad depende de quién la recibe.',
'I recommend visiting the exhibition early.|I recommend to visit the exhibition early.|En este patrón, recommend va seguido de -ing.',
"I recently visited a small exhibition about everyday life in our town a century ago. It did not have many interactive screens, but the personal letters and household objects made the stories easy to imagine. My favourite section compared two families with very different routines. Some labels were long, and younger visitors seemed to lose interest before reaching the final room. I would recommend the exhibition to people who enjoy local history and reading original accounts. Families with small children might prefer joining the short guided tour rather than reading every display. We spent about an hour there, although a careful reader could stay longer. My experience was positive, but I would not describe it as ideal for everyone. Explaining the pace and the type of material helps another visitor decide whether it suits their interests.",
'What made the stories easy to imagine?|personal letters and household objects~What might suit families with small children?|the short guided tour~How long did the writer spend there?|about an hour',
'Describe una experiencia con dos detalles concretos.|Recomiéndala a un público e indica una limitación.|Distingue tu reacción de una característica observable.',
'Escribe una reseña de 160–200 palabras con descripción, evidencia, crítica y recomendación condicionada al lector. Evita afirmaciones universales.')
add('b1',
'El proyecto final debe resolver una situación suficientemente amplia para conectar narración, opinión, planificación e interacción. Selecciona formas que sirvan a cada propósito. Una colección de ejemplos gramaticales desconectados no sustituye un mensaje con destinatario y objetivo claros.||Revisar implica comprobar coherencia entre partes: presupuesto, horarios, historia y propuesta no deben contradecirse. Señala supuestos e incertidumbres. En la presentación, responde preguntas y reformula cuando sea necesario, aunque uses una frase más sencilla que la preparada.||Valora comprensión, claridad, organización, alcance y capacidad de interacción por separado. Un texto largo no prueba por sí solo un nivel y la autoevaluación no es certificación. Guarda evidencias, repite una parte con condiciones nuevas y registra qué podrás practicar a continuación.',
'If the venue is unavailable, we will use the hall.|If the venue will unavailable, we use the hall. [plan futuro]|La condición necesita is; la consecuencia futura se expresa aquí con will use.',
"For our final project, we proposed a weekend language exchange at the community centre. We began by asking potential participants what they wanted to practise. Several had studied grammar for years but rarely used English in conversation. We designed short activities with clear purposes: giving directions, solving a travel problem and discussing a local recommendation. Last month, we tested one session with friends and discovered that our instructions were too long. We simplified them and added an example before each task. In the final presentation, we explained the budget, timetable and alternative arrangements if a room was unavailable. The teacher asked how we would include someone who felt nervous. We suggested starting in pairs and allowing preparation time. The project was not perfect, but we could explain our choices, respond to objections and revise the plan. Those abilities gave us better evidence of learning than the number of pages we had completed.",
'What did several participants lack?|conversation practice~What problem appeared in the trial?|the instructions were too long~How would they support nervous participants?|start in pairs and allow preparation time',
'Presenta una propuesta con experiencia previa y razones.|Responde a una objeción y adapta una condición.|Evalúa por separado comprensión, claridad e interacción.',
'Crea un proyecto con informe de 200 palabras, presentación de tres minutos y preguntas. Una semana después, cambia público o presupuesto y prepara una segunda versión sin copiar.')

if __name__ == '__main__':
    for level, name in [('a1','course.json'),('a2','course-a2.json'),('b1','course-b1.json')]:
        original = json.loads((ROOT/'src'/name).read_text())
        units = original['units']
        assert len(PACKS[level]) == len(units) == 24
        for u, p in zip(units, PACKS[level]):
            p['id'] = u['id']
            assert len(p['contrast']) == 3 and len(p['facts']) == 3 and len(p['transfer']) == 3
            assert all(len(f)==2 for f in p['facts'])
            p['insights'] = [dict(title=r['title'],text=t) for r,t in zip(u['rules'],p['insights'])]
            p['readTitle'] = f"Caso {u['id']}: {u['title']}"
            p['glossary'] = glossaries(level)[u['id']-1]
            known={v['en'].casefold() for v in u['vocab']}
            for v in p['glossary']:
                if v['en'].casefold() not in known:
                    u['vocab'].append(v)
                    known.add(v['en'].casefold())
        (ROOT/'src'/name).write_text(json.dumps(original,ensure_ascii=False,indent=2)+'\n')
    target=ROOT/'src'/'deep-course.json'
    target.write_text(json.dumps(PACKS,ensure_ascii=False,indent=2)+'\n')
    print('Talleres:',sum(map(len,PACKS.values())))
    print('Palabras nuevas:',sum(len(json.dumps(p,ensure_ascii=False).split()) for ps in PACKS.values() for p in ps))
